insert into public.benefits (id, name, provider, level, state, category, summary, cards, card_sets, requires, excludes, counts_in_total, eligibility_text, value_text, max_annual_value, value_period, how_to_claim, phone, source_url, notes)
values
('ACT-001', 'Electricity, Gas and Water Rebate (Utilities Concession)', 'ACT Revenue Office (via electricity retailer)', 'State', 'ACT', 'Bills', 'Up to $800 a year off your electricity bill to help with energy and water costs.', array['PCC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Primary holder of a Pensioner Concession Card, Health Care Card or Low Income Health Care Card, Veteran Gold Card (POW, War Widow or TPI embossed) or ACT Services Access Card; electricity account in your name at your principal place of residence; one rebate per household. Commonwealth Seniors Health Card not eligible.', '$800 a year, applied as a daily rate on your electricity bill', 800, '2026-27', 'Contact your energy retailer. Residents of caravan parks or retirement villages with embedded networks apply to the ACT Revenue Office online.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/community-assistance/utilities-concession', 'Only DVA Gold cards embossed POW, War Widow or TPI qualify. HCC holders must reapply each time a new card is issued. Rebate raised to $800 and made permanent in 2025-26 per revenue.act.gov.au/changes-for-2025-26. Icon Water''s page still shows the old $604 figure (outdated). ACT Services Access Card is not in schema card codes.'),
('ACT-002', 'Life Support Rebate', 'ACT Revenue Office (via electricity retailer)', 'State', 'ACT', 'Health', '$150 a year off electricity if someone at home uses life support equipment such as oxygen or dialysis.', array['NONE']::text[], null, array['life_support','electricity_account']::text[], array[]::text[], true, 'Household member uses eligible life support equipment (dialysis machine, oxygen concentrator, respirator, CPAP, nebuliser, TPN device, others on approval); letter from medical practitioner needed. One rebate per household.', '$150 a year (about 41.1 cents a day) off your electricity bill', 150, '2026-27', 'Contact your energy retailer with a letter from your doctor. Embedded-network residents apply to the ACT Revenue Office.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/life-support-rebate', 'Page does not say a concession card is required for the main life support category.'),
('ACT-003', 'Medical Heating and Cooling (Life Support Rebate sub-category)', 'ACT Revenue Office (via electricity retailer)', 'State', 'ACT', 'Health', 'Concession card holders with a condition needing medical heating or cooling can get the Life Support Rebate on electricity.', array['PCC','HCC','DVA_GOLD']::text[], null, array['medical_condition','electricity_account']::text[], array[]::text[], true, 'Concession card holder with an eligible condition that requires medical heating and/or cooling; medical letter needed.', 'Life Support Rebate amount ($150 a year)', 150, '2026-27', 'Contact your energy retailer with a letter from your doctor.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/life-support-rebate', 'The page names this as a sub-category of the Life Support Rebate but does not list the qualifying conditions or exact cards; card list assumed from Utilities Concession, confirm.'),
('ACT-004', 'Home Haemodialysis Rebate', 'ACT Revenue Office (via ActewAGL for Icon Water)', 'State', 'ACT', 'Health', 'Up to $1,200 a year off water costs if someone at home uses a home dialysis machine.', array['NONE']::text[], null, array['life_support','water_account']::text[], array[]::text[], true, 'Owner or joint owner of the property (or treated person lives there permanently); doctor''s letter confirming home dialysis treatment. Also automatically eligible for the Life Support Rebate.', 'Up to $1,200 a year ($3.29 a day) off water costs', 1200, 'Current', 'Contact ActewAGL (agent for Icon Water).', '13 14 93', 'https://www.revenue.act.gov.au/cost-of-living-support/home-haemodialysis-rebate', null),
('ACT-005', 'Pensioner General Rates Rebate', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', '50% off your general rates, up to $750 a year, plus $133 off the emergency services levy.', array['PCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Hold a Pensioner Concession Card (Services Australia or DVA) or Veteran Gold Card; property is your principal place of residence. Joint owners share the rebate by ownership share.', '50% of rates capped at $750 a year, plus $133 off the Police, Fire and Emergency Services Levy', 883, 'Cap applies from 2021-22 (still current)', 'Apply online with your ACT Digital Account, rates account number and card details. Rebate starts from the financial year you apply.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/rates-assistance/pensioners', 'max_annual_value combines $750 rates cap and $133 levy rebate. Phone is the ACT Revenue Office general line used on other ACT Revenue pages, not listed on this page.'),
('ACT-006', 'Pensioner Rates Deferral', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'Pensioners can put off paying the rest of their rates until the home is sold, with low simple interest.', array['PCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Eligible pensioner (PCC or Veteran Gold Card), principal place of residence. Defer all or part of rates left after the rebate.', 'Defer rates; concessional simple interest (reset each July and January)', null, 'Ongoing', 'Apply online with your ACT Digital Account and rates account number.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/rates-assistance/pensioners', 'Interest rate not stated on the page.'),
('ACT-007', 'Rates Deferral for People Aged 65 or Over', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'If you are 65 or older and own at least 75% of your home, you can put off paying rates until the home is sold.', array['NONE']::text[], null, array['homeowner','aged_65']::text[], array[]::text[], true, 'Aged 65 or over with at least 75% equity in your principal place of residence.', 'Defer rates; concessional simple interest', null, 'Ongoing', 'Apply online with your ACT Digital Account and rates account number.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/rates-assistance/age-65-or-over', 'Interest rate not stated on the page.'),
('ACT-008', 'Rates Deferral for Health Care Card Holders', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'Health Care Card holders who own their home can put off paying rates until it is sold.', array['HCC']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Own the property, principal place of residence, current Services Australia Health Care Card or Low Income Health Care Card.', 'Defer rates; concessional simple interest', null, 'Ongoing', 'Apply online with your ACT Digital Account, rates account number and card details.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/rates-assistance/health-care-card-and-low-income-health-care-card-holders', null),
('ACT-009', 'Rates Deferral for Financial Hardship', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'Homeowners in serious financial hardship can ask to delay paying rates or get a payment plan.', array['NONE']::text[], null, array['homeowner','hardship']::text[], array[]::text[], true, 'Property owner in significant financial hardship; principal place of residence. Referral from a financial counsellor or welfare agency is considered.', 'Defer rates with concessional interest, or an instalment plan', null, 'Ongoing', 'Complete the Rates Deferral (Hardship) Application Form with supporting documents.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/rates-assistance/financial-hardship', null),
('ACT-010', 'Pensioner Duty Concession Scheme', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'Pensioners selling their home and buying another pay no stamp duty from 1 July 2026.', array['PCC','DVA_GOLD']::text[], null, array['homeowner','age_pension']::text[], array[]::text[], true, 'At least one buyer receives the age pension (Services Australia or DVA), disability support pension and aged 50+, a DVA Gold Card, or (from 1 July 2026) a DVA Service Pension. Must sell your current home within one year, live in the new home for at least a year, and own no other land.', 'No stamp duty on the new home or land (no property value limit from 1 July 2026). In 2025-26: no duty up to $1,020,000, maximum concession $35,238.', null, 'From 1 July 2026', 'Complete the Buyer Verification Declaration before title transfer, using concession code PDC24.', '(02) 6207 0028 (option 3)', 'https://www.revenue.act.gov.au/home-buyer-assistance/pensioner-duty-concession-scheme', 'One-off, so max_annual_value null. Cannot have previously claimed the Over 60s Home Bonus. Card list approximates pension status; the test is receiving the pension, not holding a card.'),
('ACT-011', 'Pensioner Duty Deferral Scheme', 'ACT Revenue Office', 'State', 'ACT', 'Home and Rates', 'Pensioners can pay stamp duty on a new home later in instalments instead of all at once.', array['PCC','DVA_GOLD']::text[], null, array['age_pension']::text[], array[]::text[], true, 'At least one buyer is a pensioner (age pension, DSP aged 50+, DVA Gold Card, or DVA Service Pension from 1 July 2026) and lives in the home for at least one year. Can combine with the concession if at least $1,000 of duty remains.', 'Defer stamp duty, paid by direct debit over set periods', null, 'Ongoing', 'Complete the Buyer Verification Declaration before title transfer, using code PDD25.', '(02) 6207 0028 (option 3)', 'https://www.revenue.act.gov.au/home-buyer-assistance/pensioner-duty-deferral-scheme', null),
('ACT-012', 'Spectacles Subsidy Scheme', 'ACT Revenue Office', 'State', 'ACT', 'Health', 'Up to $200 towards new glasses every two years.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card (Services Australia or DVA) or Health Care Card held at least three months. Commonwealth Seniors Health Card not eligible.', 'Up to $200 every two years', 100, 'Current', 'Get the form from a registered optometrist, who lodges it for you.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/spectacles-subsidy-scheme', 'max_annual_value is $200 averaged over two years.'),
('ACT-013', 'Low Vision Aids Scheme', 'ACT Revenue Office (via Vision Australia)', 'State', 'ACT', 'Health', 'Up to $100 every two years towards magnifiers and other low vision aids.', array['PCC','HCC']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'ACT resident with a Pension Concession Card (Services Australia or DVA) or Health Care Card held 3 months or more, with low vision. CSHC not eligible.', 'Up to $100 every two years', 50, 'Current', 'Get an application form from Vision Australia, which processes it with the ACT Revenue Office.', '1300 84 74 66', 'https://www.revenue.act.gov.au/cost-of-living-support/low-vision-aids-scheme', 'max_annual_value is $100 averaged over two years.'),
('ACT-014', 'Taxi Subsidy Scheme', 'ACT Revenue Office', 'State', 'ACT', 'Transport', 'Pays 50% or 75% of taxi fares for people whose disability stops them using public transport.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Permanent ACT resident with a severe or profound activity limitation preventing public transport use (mobility, vision, cognitive, psychiatric, uncontrolled epilepsy); form signed by doctor or OT.', '50% or 75% of fare, up to $31 / $47.50 per trip, up to 854 trips a year', null, '1 Jul 2026 to 30 Jun 2027', 'Complete the Membership Application Form with Part B signed by a doctor or occupational therapist.', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/taxi-subsidy-scheme', null),
('ACT-015', 'Funeral Assistance Program', 'ACT Revenue Office (via participating funeral directors)', 'State', 'ACT', 'Payments', 'Up to $500 towards a funeral for an immediate family member if you are in financial hardship.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'ACT resident in financial hardship unable to meet the full cost of a funeral for an immediate family member; financial assessment of income, expenses and assets.', 'Up to $500 contribution', null, 'Current', 'Apply through a participating funeral provider (Tobin Brothers, Toscan Dinn, William Cole, Tender Funerals).', '(02) 6207 0028 (option 5)', 'https://www.revenue.act.gov.au/cost-of-living-support/funeral-assistance', 'One-off, so max_annual_value null.'),
('ACT-016', 'ACT Seniors Card', 'ACT Government and COTA ACT', 'State', 'ACT', 'Discounts', 'Free card for Canberrans 60+ giving discounts at about 300 businesses and transport concessions.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or over, permanent ACT resident, not working more than 20 hours a week in paid work.', 'Free card; discounts at about 300 participating businesses', null, 'Ongoing', 'Apply online through the ACT Government form; card posted within 15 business days. COTA ACT can help.', '02 6282 3777', 'https://www.accesscanberra.act.gov.au/identity/proof-of-identity-and-residency/act-seniors-card', 'Combined Seniors Card/MyWay card can no longer be used to tap on public transport. Discount directory at actseniorscard.org.au.'),
('ACT-017', 'Free public transport for seniors aged 70+', 'Transport Canberra', 'State', 'ACT', 'Transport', 'ACT seniors aged 70 and over travel free on buses and light rail at any time.', array['SENIORS_CARD']::text[], null, array['aged_70']::text[], array[]::text[], true, 'ACT seniors aged 70 and over with a registered MyWay+ seniors concession.', 'Free bus and light rail travel', null, 'Current', 'Register the seniors concession in your MyWay+ account and link a card; carry proof of concession.', '13 17 10', 'https://www.transport.act.gov.au/tickets-and-myway/concessions', 'Seniors concessions last 3 years from validation.'),
('ACT-018', 'Free off-peak public transport for concession holders', 'Transport Canberra', 'State', 'ACT', 'Transport', 'Free bus and light rail off-peak (9am to 4:30pm and after 6pm weekdays, all weekend) for pensioners, card holders and seniors 60-69.', array['PCC','HCC','DVA_GOLD','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Health Care Card or Pension Card, ACT Services Access Card, DVA Gold Card, ACT Seniors Card (aged 60-69) or interstate seniors card holders.', 'Free off-peak travel; concession fares at other times', null, 'Current', 'Register your concession in MyWay+ and link a contactless or MyWay+ card; carry proof.', '13 17 10', 'https://www.transport.act.gov.au/tickets-and-myway/concessions', 'Most non-seniors MyWay+ concessions expired 30 June 2026 and must be revalidated. CSHC not mentioned. Peak concession fare amounts not on page.'),
('ACT-019', 'Free public transport for DVA TPI/EDA Gold Card holders', 'Transport Canberra', 'State', 'ACT', 'Transport', 'Veterans with a TPI or EDA Gold Card, and a companion, travel free on buses and light rail.', array['DVA_GOLD']::text[], null, array['veteran']::text[], array[]::text[], true, 'DVA Gold Card holders with TPI or EDA, plus their companion.', 'Free bus and light rail travel', null, 'Current', 'Register the concession in MyWay+.', '13 17 10', 'https://www.transport.act.gov.au/tickets-and-myway/concessions', null),
('ACT-020', 'Flexible Bus Service', 'Transport Canberra', 'State', 'ACT', 'Transport', 'Free door-to-door style bus for people 70+ or with mobility difficulty, weekdays 9:30am to 1:30pm.', array['NONE']::text[], null, array['aged_70']::text[], array[]::text[], true, 'Assessed case by case: aged 70 or older, Disability Pension Card holder with mobility difficulty, disability preventing use of regular buses, or Vision Impaired/TPI/Permanent Impairment travel pass holder.', 'Free', null, 'Current', 'Call or email fbs@act.gov.au by 4:30pm the business day before travel.', '(02) 6205 3555', 'https://www.transport.act.gov.au/travel-options/bus/accessible-travel/flexible-bus-service', 'Age 70 is one of several alternative criteria (not all required).'),
('ACT-021', 'Community bus for older Canberrans', 'ACT Government (regional community services)', 'State', 'ACT', 'Transport', 'Weekday community bus for older people who find other transport hard to use.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'ACT residents who find it hard to use other transport, including older people with mobility or confidence problems and people in retirement facilities.', 'Cost set by each regional service', null, 'Current', 'Call your nearest regional community service to register and book.', '02 6278 8124 (Belconnen); see page for other regions', 'https://www.act.gov.au/community/older-canberrans/community-bus', 'Fees not stated on source.'),
('ACT-022', 'Registration concession (pensioners)', 'Access Canberra', 'State', 'ACT', 'Transport', 'No registration fee for one car if you hold a Pensioner Concession Card, Low Income Health Care Card or DVA Gold Card.', array['PCC','HCC','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Services Australia PCC or Low Income Health Care Card, DVA PCC or Gold Card, or ACT Services Access Card. One light vehicle or light trailer in the cardholder''s name. DVA White/Orange cards not eligible.', 'Zero registration fee (MAI insurance and other fees still payable)', null, 'Current', 'Visit an Access Canberra Service Centre with ID, concession proof and the Concession validation consent form.', '13 22 81', 'https://www.accesscanberra.act.gov.au/driving-transport-and-parking/registration/concessions-for-registration-fees', 'Dollar value of the waived registration fee not shown on this page. Standard Health Care Card holders: only the Low Income HCC is listed.'),
('ACT-023', 'Registration discount for Seniors Card holders', 'Access Canberra', 'State', 'ACT', 'Transport', '10% off car registration (28% for gas-powered vehicles) for ACT Seniors Card holders.', array['SENIORS_CARD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'ACT Seniors Card holder; one light vehicle in your name.', '10% off registration fee (28% for gas vehicles); full MAI and other fees', null, 'Current', 'Call Access Canberra or visit a Service Centre to link your Seniors Card to your vehicle.', '13 22 81', 'https://www.accesscanberra.act.gov.au/driving-transport-and-parking/registration/concessions-for-registration-fees', null),
('ACT-024', 'Driver licence concession', 'Access Canberra', 'State', 'ACT', 'Transport', 'Free driver licence renewal for Pensioner Concession Card and DVA Gold Card holders.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Centrelink or DVA Pension Concession Card, or DVA Gold Card. Applies to full, provisional and heavy vehicle licences.', '100% off licence issue or renewal fees', null, 'Current', 'Visit an Access Canberra Service Centre with your licence, card and Concession validation consent form (DVA: letter or UIN).', '13 22 81', 'https://www.accesscanberra.act.gov.au/driving-transport-and-parking/licences/concessions-for-driver-licence-fees', 'No age-based (e.g. 75+) licence discount listed. Licence fee amount not on page.'),
('ACT-025', 'Safe driver licence renewal discount', 'Access Canberra', 'State', 'ACT', 'Transport', '30% off your licence renewal if you have had no driving offences for 5 years.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'ACT resident with a full licence held continuously for 5 years and no traffic or camera infringements or driving convictions in that time.', '30% off licence renewal', null, 'Current', 'Applied automatically at renewal.', '13 22 81', 'https://www.accesscanberra.act.gov.au/driving-transport-and-parking/licences/concessions-for-driver-licence-fees', null),
('ACT-026', 'Free ambulance for pensioners and concession card holders', 'ACT Ambulance Service (ESA)', 'State', 'ACT', 'Health', 'Most aged pension and health care card holders pay nothing for ACT ambulance services.', array['PCC','HCC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Most aged pension and health care concession card holders are entitled to free ambulance services within the ACT. DVA card holders: DVA endorses the account.', 'Ambulance fees waived (emergency transport fee is $1,180 in 2024-25)', null, '2024-25 fee schedule', 'Send a copy of the front and back of your card to SSAF@act.gov.au or the address on the account; DVA holders contact DVA.', '02 6207 9990', 'https://esa.act.gov.au/about-esa-emergency-services/ambulance/fees-and-charges', 'Source says ''most'' card holders, without exact card list. DVA_WHITE only covers accepted conditions via DVA. Ambulance cover outside the ACT not included. ACT has no ambulance levy exemption as such.'),
('ACT-027', 'Public adult dental service', 'Canberra Health Services', 'State', 'ACT', 'Health', 'Low-cost public dental care for adults with a concession card, including CSHC holders.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'ACT resident and primary holder of a Pensioner Concession Card or Health Care Card, DVA Veteran Card (white or gold), ACT Services Access Card or Commonwealth Seniors Health Card.', 'Co-payments: general treatment capped at $577.80 per treatment plan; emergency appointment $55.15', null, 'Current', 'Call Central Health Intake with your Medicare and concession card details.', '(02) 5124 9977', 'https://www.canberrahealthservices.act.gov.au/services-and-clinics/services/dental-adult', 'Value is a subsidised service, not a cash amount. Waiting lists apply for restorative and denture work.'),
('ACT-028', 'Interstate Patient Travel Assistance Scheme (IPTAS)', 'ACT Health / Canberra Health Services', 'State', 'ACT', 'Health', 'Help with travel and accommodation costs if you must go interstate for specialist treatment not available in the ACT.', array['NONE']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'Permanent ACT or Jervis Bay resident with Medicare, referred by an ACT or Queanbeyan medical professional to the closest interstate service; treatment not available in the ACT.', 'Subsidy towards car, public transport or flight costs and accommodation', null, 'Current', 'Lodge the IPTAS claim form within six months of travel.', '(02) 5124 0000', 'https://www.canberrahealthservices.act.gov.au/before,-during-and-after-your-care/staying-at-canberra-hospital/before-you-arrive/getting-here-and-getting-around/travelling-from-outside-canberra', 'Per-km and per-night rates are in the IPTAS Assessment Guidelines PDF, not opened. Phone is the hospital switchboard.'),
('ACT-029', 'Home Energy Support Program', 'ACT Government (Climate Choices)', 'State', 'ACT', 'Home and Rates', 'Rebates of up to $5,000 for concession card homeowners to install solar, efficient heating, hot water, stoves or insulation.', array['PCC','HCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'ACT resident homeowner living in the home, with a PCC, DVA Gold Card or Health Care Card; attended a free Everyday Climate Choices workshop; unimproved land value up to $750,000 (houses) or $300,000 (apartments). Renters not eligible.', '50% of costs up to $2,500 for rooftop solar plus 50% up to $2,500 for other products (up to $5,000 total); optional zero-interest loan up to $10,000', null, 'Current', 'Attend a workshop, get quotes from accredited suppliers via Brighte, apply before installation, then claim after.', '1300 141 777', 'https://www.climatechoices.act.gov.au/policy-programs/home-energy-support-rebates-for-homeowners', 'One-off rebate, so max_annual_value null. No end date stated.'),
('ACT-030', 'Access to Electric Program', 'ACT Government (with Care Financial Counselling)', 'State', 'ACT', 'Home and Rates', 'Free replacement of gas appliances with efficient electric ones for homeowners struggling to pay energy bills.', array['NONE']::text[], null, array['homeowner','hardship','gas_account']::text[], array[]::text[], true, 'Homeowners in financial hardship who regularly struggle to pay energy bills; eligibility assessed by Care Financial Counselling.', 'Fully funded electric heating/cooling, hot water, cooktop and insulation upgrades', null, 'Status not stated (page modified Feb 2025)', 'Complete the online self-assessment or contact Care Financial Counselling.', '02 6257 1788', 'https://www.climatechoices.act.gov.au/policy-programs/access-to-electric-program', 'Confirm program still open.'),
('ACT-031', 'Home Energy Efficiency Program (free energy advice and draught-proofing)', 'St Vincent de Paul for ACT Government', 'State', 'ACT', 'Bills', 'Free home visit, energy-saving advice and draught-proofing for low-income households.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card (Centrelink or DVA), Low Income Health Care Card, or within NRAS income limits.', 'Free assessment, information kit and draught-proofing help', null, 'Current', 'Contact the St Vincent de Paul Energy Efficiency team.', '6234 7408', 'https://www.climatechoices.act.gov.au/policy-programs/home-energy-efficiency-program', null),
('ACT-032', 'Sustainable Household Scheme loans', 'ACT Government (via Brighte)', 'State', 'ACT', 'Home and Rates', 'Low-interest loans of $2,000 to $20,000 for solar, batteries, efficient appliances or an electric car.', array['NONE']::text[], null, array['homeowner']::text[], array[]::text[], true, 'ACT resident homeowner (or licence holder for EV loans); attend a free workshop; meet Brighte lending criteria.', 'Loan $2,000 to $20,000 at 3%, up to 10 years', null, 'From 1 July 2026', 'Apply through Brighte after attending a workshop.', '1300 141 777', 'https://www.climatechoices.act.gov.au/policy-programs/sustainable-household-scheme', 'A loan, not a grant. Concession holders should use the Home Energy Support Program for zero-interest loans.'),
('ACT-033', 'Free first green garden bin for concession holders', 'City Services ACT', 'State', 'ACT', 'Discounts', 'Pensioners and Seniors Card holders pay no registration fee for a green garden waste bin.', array['PCC','DVA_GOLD','SENIORS_CARD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'ACTION Gold Card, DVA Gold Card, Centrelink Pensioner Concession Card or ACT Seniors Card holder.', 'One-off bin registration fee waived; annual service fee applies for second bins', null, 'Current', 'Order a green bin online through City Services.', '13 22 81', 'https://www.cityservices.act.gov.au/recycling-and-waste/types-of-waste/garden-waste', 'Fee amounts not on page. Homeowner tag is an assumption; renters may also order. Phone is Access Canberra (not on page).'),
('ACT-034', 'Free bulky waste collection', 'City Services ACT', 'State', 'ACT', 'Discounts', 'One free bulky waste pick-up (up to 2 cubic metres) each financial year for Canberra households.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'Canberra households; one collection per financial year, up to 2 cubic metres.', 'One free collection a year', null, 'Each financial year', 'Book online up to 6 months ahead (closes 14 days before collection).', '02 6205 9521', 'https://www.cityservices.act.gov.au/recycling-and-waste/bulky-waste-collection', 'Not concession-specific.'),
('ACT-035', 'Recreational fishing - no licence needed', 'ACT Government', 'State', 'ACT', 'Discounts', 'You do not need a licence to fish recreationally in ACT public waters.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'Anyone fishing in ACT public waters (not Googong Reservoir, which follows NSW rules).', 'No licence fee', null, 'Current', 'No action needed; follow ACT fishing rules.', '13 22 81', 'https://www.act.gov.au/environment/animals-and-plants/animals/wildlife-management/fish/recreational-fishing-in-the-act', 'Included so the site can tell ACT users there is no fishing licence to concession.'),
('FED-001', 'Age Pension', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A fortnightly pension for people 67 or older who pass the income and assets tests.', array['NONE']::text[], null, array['aged_67']::text[], array['age_pension']::text[], false, 'Age 67 or older; within the income and assets test limits; Australian resident, normally for at least 10 years.', 'Up to $1,237.70 a fortnight single, or $933.00 each for a couple ($1,866.00 combined), including Pension Supplement and Energy Supplement', 32180.2, '20 Sep 2026 to 19 Mar 2027', 'Claim online through myGov (Centrelink online account) or at a service centre.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/8/10', 'Max annual = single fortnightly x 26. Basic rate alone $1,135.40 single / $855.90 each couple. Assets test free area from 1 Jul 2026: $333,000 single homeowner / $600,000 non-homeowner; $499,000 / $766,000 couple (guides.dss.gov.au 4/10/3). Income free area $5,876 pa single, $5,148 pa each couple. Services Australia rate page still showed older $1,178.70 when fetched. Eligibility from servicesaustralia.gov.au/age-pension.'),
('FED-002', 'Pension Supplement', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'An extra amount paid with your pension to help with everyday costs such as bills.', array['NONE']::text[], null, array['age_pension']::text[], array[]::text[], true, 'Paid automatically with Age Pension, Carer Payment and other pensions.', 'Up to $88.20 a fortnight single, $66.50 each for a couple (minimum $47.50 single / $35.80 each)', null, 'From 20 Sep 2026', 'Paid automatically with your pension; no separate claim.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/9/10', 'Already included in the Age Pension maximum; max_annual_value left null to avoid double counting.'),
('FED-003', 'Energy Supplement (Commonwealth Seniors Health Card holders)', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Bills', 'A quarterly payment to help with energy costs for some CSHC holders who got their card before 20 March 2017.', array['CSHC']::text[], null, array[]::text[], array[]::text[], true, 'Commonwealth Seniors Health Card holders who were already getting it; closed to new CSHC holders from 20 March 2017. Pensioners get it inside their pension.', '$366.60 a year single ($91.65 a quarter), $275.60 a year each for a couple', 366.6, 'Current annual rate (DSS guide reviewed 2 Jan 2026)', 'Paid automatically each quarter if you are eligible.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/10/20', 'Pension recipients receive $14.10 a fortnight single / $10.60 each couple inside the pension. DVA CLIK lists quarterly payment for quarter to 19/12/2026 at $91.65 single / $68.90 partnered.'),
('FED-004', 'Work Bonus', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'Lets pensioners earn some work income without it reducing their pension.', array['NONE']::text[], null, array['age_pension']::text[], array[]::text[], true, 'Pensioners over Age Pension age who receive a pension (also applies to DVA pensions).', 'First $300 a fortnight of work income is not counted; unused amounts build up to a balance of $11,800', null, 'Current', 'Applied automatically when you report your employment income to Centrelink.', null, 'https://servicesaustralia.gov.au/how-work-bonus-works', 'Not a cash payment; value depends on earnings.'),
('FED-005', 'Rent Assistance', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Home and Rates', 'Extra money paid with your pension if you pay private rent or certain other housing costs.', array['NONE']::text[], null, array['renter','age_pension']::text[], array[]::text[], false, 'People getting an income support payment such as Age Pension who pay rent above the threshold (not public housing).', 'Up to $223.80 a fortnight single ($149.20 if sharing), $211.00 a fortnight combined for a couple; 75c for every $1 of rent above $157.80 (single) / $255.80 (couple)', 5818.8, 'From 20 Sep 2026', 'Tell Centrelink your rent details when you claim your pension or through your online account.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/7/10', 'Max annual = single max x 26. Services Australia page still showed older $215.40 rate when fetched.'),
('FED-006', 'Remote Area Allowance', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A small extra payment if you live in a remote part of Australia and get an income support payment.', array['NONE']::text[], null, array['rural','age_pension']::text[], array[]::text[], true, 'Income support recipients living in a designated remote area (tax zone A or special areas).', '$18.20 a fortnight single, $15.60 each for a couple', 473.2, 'Current (not indexed; page reviewed 20 Mar 2026)', 'Usually added automatically when Centrelink has your remote address.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/7/70', 'Remote-area definition not on the fetched page.'),
('FED-007', 'Pensioner Concession Card', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Discounts', 'A card for pensioners that gives cheaper medicines and health care and unlocks state, council and business discounts.', array['PCC']::text[], null, array['age_pension']::text[], array['PCC']::text[], true, 'Given to people who get certain Centrelink payments, including Age Pension.', 'Cheaper PBS medicines, bulk-billing incentives and access to many state and private concessions', null, 'Current', 'Issued automatically when you are granted a qualifying pension.', null, 'https://www.servicesaustralia.gov.au/pensioner-concession-card', 'Laminated cards issued from December 2025; old and new both valid.'),
('FED-008', 'Commonwealth Seniors Health Card', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Health', 'A card for self-funded retirees of pension age that gives cheaper medicines and some concessions.', array['CSHC']::text[], null, array['aged_67']::text[], array['CSHC','PCC']::text[], true, 'Age Pension age or older, meet residence rules, not getting a Centrelink/DVA income support payment, and income under the limit (no assets test).', 'Income limits: under $101,105 a year single, $161,768 a year combined for a couple ($202,210 if separated by illness)', null, 'Current limits shown on Services Australia', 'Apply through your Centrelink online account via myGov.', null, 'https://www.servicesaustralia.gov.au/income-test-for-commonwealth-seniors-health-card', 'Account-based income streams are deemed. Benefits: PBS concession rate, PBS Safety Net, bulk-billing incentives, Extended Medicare Safety Net concessional threshold, discretionary state/private concessions (guides.dss.gov.au 3/9/3/20).'),
('FED-009', 'Home Equity Access Scheme', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A government loan against your home that tops up your income with fortnightly payments or lump sums.', array['NONE']::text[], null, array['homeowner','aged_67']::text[], array[]::text[], true, 'Age Pension age (or partner of someone who is); qualify for Age Pension, DSP or Carer Payment (need not be paid it); own Australian real estate as security with adequate insurance; not bankrupt.', 'Pension plus loan up to 150% of the maximum pension rate; lump-sum advances up to 50% of the annual maximum pension rate (max 2 per 26 fortnights); interest 3.95% a year compounding fortnightly; no negative equity guarantee', null, 'Interest rate 3.95% (from 1 Jan 2022, still current per DSS guide)', 'Apply through Centrelink; for an existing loan use form D9390 for an advance.', null, 'https://guides.dss.gov.au/social-security-guide/3/4/5/10', 'Formerly the Pension Loans Scheme. A loan, not a grant. Interest rate from guides.dss.gov.au 3/4/5/45; advance rules from servicesaustralia.gov.au/home-equity-access-scheme-advance-payments.'),
('FED-010', 'Carer Payment', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'An income support payment if you give constant care to someone with a disability, illness or who is frail aged.', array['NONE']::text[], null, array['carer']::text[], array[]::text[], false, 'Provide constant care to someone with a severe disability, medical condition or who is frail aged; pass income and assets tests.', 'Up to $1,237.70 a fortnight single, $933.00 each for a couple (same as pension rates)', 32180.2, '20 Sep 2026 to 19 Mar 2027', 'Claim online through your Centrelink account with a care needs assessment.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/8/10', 'Carer Payment uses common pension rates (DSS guide 5/1/5/20). Cannot be received at the same time as Age Pension. Services Australia page showed older rates when fetched.'),
('FED-011', 'Carer Allowance', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A fortnightly supplement if you give daily care to someone with a disability, medical condition or who is frail aged.', array['NONE']::text[], null, array['carer']::text[], array[]::text[], false, 'You give daily care at home; combined income of you and your partner under $250,000 a year. Can be paid on top of Age Pension.', '$162.60 a fortnight', 4227.6, 'Current (indexed 1 January each year)', 'Claim through your Centrelink online account.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/5/50', 'Not taxable. Income limit from servicesaustralia.gov.au/how-much-carer-allowance-you-can-get.'),
('FED-012', 'Carer Supplement', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A yearly lump sum for carers who get Carer Allowance or Carer Payment.', array['NONE']::text[], null, array['carer']::text[], array[]::text[], true, 'Get Carer Allowance, Carer Payment, or DVA Carer Service Pension / Service Pension partner with Carer Allowance, for a period including 1 July.', 'Up to $600 a year', 600, '2026-27', 'Paid automatically.', null, 'https://www.servicesaustralia.gov.au/carer-supplement', null),
('FED-013', 'Carer Gateway', 'Australian Government (Department of Health)', 'Federal', 'ALL', 'Health', 'Free counselling, practical help and support services for unpaid carers.', array['NONE']::text[], null, array['carer']::text[], array[]::text[], true, 'Unpaid carers of someone with a disability, illness, mental health condition or who is frail aged.', 'Free services', null, 'Current', 'Call 1800 422 737 or apply online.', '1800 422 737', 'https://www.carergateway.gov.au/', null),
('FED-014', 'Essential Medical Equipment Payment', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Bills', 'A yearly payment to help with extra energy costs of running essential medical equipment or medically needed heating or cooling.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'You (or the person you care for) hold a PCC, HCC, CSHC or DVA Gold/White card; use essential medical equipment or need extra heating/cooling for a specified condition at home; hold or contribute to the energy account.', '$203 a year', 203, '2026-27', 'Claim through your Centrelink online account; a medical confirmation may be needed.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/10/40', 'Card list from guides.dss.gov.au 3/15/4/60.'),
('FED-015', 'Mobility Allowance', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Transport', 'A fortnightly payment to help with travel costs for people with a disability who cannot use public transport without a lot of help.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'People with disability or illness who cannot use public transport without substantial help and travel for work, study or volunteering.', '$122.80 a fortnight standard rate, $171.70 a fortnight higher rate', 4464.2, 'From 1 Jan 2026', 'Claim through Centrelink.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/5/40', 'Eligibility not on the fetched rate page; check whether it can be paid alongside Age Pension (generally aimed at people below pension age).'),
('FED-016', 'Bereavement payments', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'When a pensioner''s partner dies, the survivor keeps payments for a bereavement period and may get a lump sum.', array['NONE']::text[], null, array['age_pension']::text[], array[]::text[], true, 'Surviving partner of a pensioner couple; tell Services Australia about the death.', 'Continued payments during the bereavement period and possibly a lump sum; amount depends on circumstances', null, 'Current', 'Tell Centrelink about the death as soon as possible.', null, 'https://guides.dss.gov.au/social-security-guide/3/1/5/30', 'Bereavement period length and lump sum amounts not shown on fetched page (see DSS guide 3/1/5/70).'),
('FED-017', 'Australian Government Disaster Recovery Payment', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A one-off payment if you are seriously affected by a declared major disaster.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Seriously affected by a disaster the Government has activated the payment for.', '$1,000 per adult, $400 per child', null, 'Current (as most recently determined)', 'Claim online through myGov within the claim period after the disaster.', null, 'https://guides.dss.gov.au/social-security-guide/5/1/6/20', 'One-off; only available for activated disasters.'),
('FED-018', 'Crisis Payment', 'Services Australia (Centrelink)', 'Federal', 'ALL', 'Payments', 'A one-off payment if you get an income support payment and face a crisis such as family violence or a disaster.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Income support recipients in severe financial hardship due to an extreme circumstance.', '$618.85 single, $466.50 each partnered (per event)', null, 'From 20 Sep 2026', 'Contact Centrelink within 7 days of the event (check rules).', null, 'https://clik.dva.gov.au/node/86936', 'Rate taken from DVA CLIK 20 Sep 2026 rates table; DSS guide 5/1/6/30 not opened. Claim time limit not verified.'),
('FED-019', 'Seniors and Pensioners Tax Offset (SAPTO)', 'Australian Taxation Office', 'Federal', 'ALL', 'Payments', 'A tax offset that means many older Australians pay little or no income tax.', array['NONE']::text[], null, array['aged_67']::text[], array[]::text[], true, 'Receive an eligible Australian Government pension (or are of pension age and eligible but not paid) and rebate income below the cut-out.', 'Up to $2,230 single, $1,602 each for a couple ($2,040 each if separated by illness); cuts out at $52,759 single / $43,810 each couple', 2230, '2025-26 income year', 'Claimed automatically in your tax return.', null, 'https://www.ato.gov.au/individuals-and-families/income-deductions-offsets-and-records/tax-offsets/seniors-and-pensioners-tax-offset', 'Reduces tax payable; worth nothing if you pay no tax.'),
('FED-020', 'Downsizer super contribution', 'Australian Taxation Office', 'Federal', 'ALL', 'Home and Rates', 'Lets you put up to $300,000 from selling your home into super.', array['NONE']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Age 55+; owned the home 10+ years; sale qualifies for main residence CGT exemption; contribute within 90 days; not used before.', 'Up to $300,000 per person', null, 'Current', 'Give the Downsizer contribution form (NAT 75073) to your super fund.', null, 'https://www.ato.gov.au/individuals-and-families/super-for-individuals-and-families/super/growing-and-keeping-track-of-your-super/how-to-save-more-in-your-super/downsizer-super-contributions', 'Not cash; super balance counts in pension assets test once over pension age.'),
('FED-021', 'PBS concessional medicines', 'Department of Health (Pharmaceutical Benefits Scheme)', 'Federal', 'ALL', 'Health', 'Concession card holders pay a much lower price for PBS prescriptions.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Hold a Commonwealth concession card.', '$7.70 per PBS script (general patients pay $25.00)', null, 'From 1 Jan 2026 (current at 1 Jul 2026)', 'Show your concession card at the pharmacy.', null, 'https://www.pbs.gov.au/info/healthpro/explanatory-notes/front/fee', 'Saving depends on number of scripts. DVA card coverage of PBS concession assumed from general practice — verify.'),
('FED-022', 'PBS Safety Net', 'Department of Health (Pharmaceutical Benefits Scheme)', 'Federal', 'ALL', 'Health', 'After you spend a set amount on PBS medicines in a year, the rest of your scripts are free (for concession holders).', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Concession card holders whose family PBS spending reaches the concessional threshold in a calendar year.', 'Free PBS scripts for the rest of the year after $277.20 spent (general threshold $1,748.20)', null, 'Calendar year 2026', 'Ask your pharmacy to keep a record or use a Prescription Record Form; apply for a Safety Net card when you reach the threshold.', null, 'https://www.pbs.gov.au/info/healthpro/explanatory-notes/front/fee', 'health.gov.au PBS Safety Net page blocked to fetching.'),
('FED-023', 'Bulk billing incentives (GP visits)', 'Department of Health (Medicare)', 'Federal', 'ALL', 'Health', 'GPs get extra payments to bulk bill, so many visits cost you nothing.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'From 1 Nov 2025 incentives cover all Medicare card holders; concession card holders were already covered.', 'No out-of-pocket cost when your GP bulk bills', null, 'From 1 Nov 2025', 'Ask your GP clinic whether it bulk bills all patients.', null, 'https://www.health.gov.au/ministers/the-hon-mark-butler-mp/media/delivering-the-bulk-billing-incentive-program', 'Clinic chooses whether to bulk bill; source is a ministerial media release.'),
('FED-024', 'Extended Medicare Safety Net (concessional)', 'Department of Health (Medicare)', 'Federal', 'ALL', 'Health', 'Once your out-of-hospital medical costs pass a lower concession threshold, Medicare pays back more.', array['PCC','HCC','CSHC']::text[], null, array[]::text[], array[]::text[], true, 'Commonwealth concession card holders (and families) whose out-of-pocket costs pass the concessional threshold in a calendar year.', 'Higher Medicare rebates after threshold', null, 'Calendar year', 'Automatic once registered as a family/individual with Medicare.', null, 'https://guides.dss.gov.au/social-security-guide/3/9/3/20', 'Threshold amount not on fetched page; health.gov.au/servicesaustralia pages blocked.'),
('FED-025', 'Hearing Services Program', 'Department of Health', 'Federal', 'ALL', 'Health', 'Free or subsidised hearing tests and hearing aids for eligible pensioners and veterans.', array['PCC','DVA_GOLD','DVA_WHITE']::text[], null, array['hearing_need']::text[], array[]::text[], true, 'Australian citizens or permanent residents aged 21+ who hold an eligible card or payment; the Commonwealth Seniors Health Card does NOT qualify.', 'Subsidised hearing assessments, devices and maintenance; vouchers valid 5 years', null, 'Current', 'Apply online, through a hearing provider, or with a printed form.', '1800 500 726', 'https://www.health.gov.au/our-work/hearing-services-program/accessing/eligibility', 'Exact eligible card/payment list was not visible in fetched text; PCC and DVA Gold/White listed from program rules - verify. Maintenance fee not shown.'),
('FED-026', 'Continence Aids Payment Scheme (CAPS)', 'Department of Health (via Services Australia)', 'Federal', 'ALL', 'Health', 'A yearly payment to help buy continence products if you have permanent and severe incontinence.', array['NONE']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'Permanent and severe incontinence from an eligible condition; must meet all program requirements.', '$739.40 a year', 739.4, '2026-27', 'Apply via Medicare online account or app, or paper form with your health professional''s section completed.', null, 'https://www.health.gov.au/our-work/continence-aids-payment-scheme-caps', 'Detailed eligibility not shown on fetched page.'),
('FED-027', 'Support at Home (aged care at home)', 'Department of Health and Aged Care (via My Aged Care)', 'Federal', 'ALL', 'Health', 'Government-funded help at home such as nursing, personal care, cleaning and gardening; full pensioners pay the lowest contributions.', array['NONE']::text[], null, array['aged_65']::text[], array[]::text[], true, 'Older people assessed as needing help at home through My Aged Care; contributions depend on pension status and an income/assets assessment.', 'Clinical care free; contributions for independence and everyday living services; lifetime contribution cap $135,318.69', null, 'Cap as at 1 Nov 2025', 'Contact My Aged Care to arrange an assessment.', null, 'https://www.health.gov.au/our-work/support-at-home/charging-for-support-at-home-services/support-at-home-participant-contributions', 'Exact contribution percentages not on fetched page; aged_65 is the general entry age (50 for First Nations) - not stated on this page.'),
('FED-028', 'Commonwealth Home Support Programme (CHSP)', 'Department of Health and Aged Care (via My Aged Care)', 'Federal', 'ALL', 'Health', 'Low-cost entry-level help at home such as meals, transport, cleaning and home maintenance.', array['NONE']::text[], null, array['aged_65']::text[], array[]::text[], true, 'Older people assessed as eligible for CHSP services; pay a contribution based on ability to pay.', 'You pay only a contribution, never the full cost; hardship policies apply', null, 'Current', 'Contact My Aged Care for an assessment, then agree fees with a provider.', null, 'https://www.myagedcare.gov.au/commonwealth-home-support-program-costs', 'Age criterion not stated on fetched page.'),
('FED-029', 'Concession stamps', 'Australia Post', 'Private', 'ALL', 'Discounts', 'Buy up to 75 discounted stamps a year for 60c each.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Holders of a Pensioner Concession Card, Health Care Card, Commonwealth Seniors Health Card, DVA card or Veterans'' Repatriation Health Card.', '60c per stamp instead of $1.85, up to 75 a year', 93.75, 'Current', 'Fill in the MyPost Concession account form and take it with your card to a Post Office; then show your MyPost Concession card to buy.', null, 'https://auspost.com.au/personal/sending/stamps/concession-stamps', 'Max annual value calculated as 75 x ($1.85 - $0.60).'),
('FED-030', 'No Interest Loan Scheme (NILS)', 'Good Shepherd, funded by Department of Social Services', 'Federal', 'ALL', 'Payments', 'Interest-free, fee-free loans for essentials like appliances, car repairs or medical costs.', array['PCC','HCC']::text[], null, array['low_income']::text[], array[]::text[], true, 'Age 18+ and hold a Health Care or Pension card, or income under $70,000 single / $100,000 with partner or dependants, or experienced family violence in last 10 years.', 'Up to $2,000 for essentials, $5,000 for vehicles, $3,000 for disaster relief or rental bonds', null, 'Current', 'Use the eligibility checker or find a local provider at nils.com.au.', null, 'https://nils.com.au/', 'Loan, must be repaid.'),
('FED-031', 'Service Pension (DVA)', 'Department of Veterans'' Affairs', 'Federal', 'ALL', 'Payments', 'An income support pension for eligible veterans and their partners, paid at the same rate as Age Pension.', array['DVA_GOLD','DVA_WHITE','NONE']::text[], null, array['veteran']::text[], array[]::text[], false, 'Eligible veterans with qualifying service (and partners) who meet age and income/assets tests.', 'Up to $1,237.70 a fortnight single, $933.00 each for a couple', 32180.2, 'From 20 Sep 2026', 'Claim through DVA (MyService).', null, 'https://clik.dva.gov.au/node/86936', 'Eligibility details not on fetched page (DVA service pension page blocked to fetching).'),
('FED-032', 'Veterans'' Supplement', 'Department of Veterans'' Affairs', 'Federal', 'ALL', 'Payments', 'A small fortnightly supplement for some veterans and war widows who do not get an income support payment.', array['DVA_GOLD','DVA_WHITE']::text[], null, array['veteran']::text[], array[]::text[], true, 'High rate: Gold Card holders on certain disability compensation payments without income support; low rate: certain war widows, White/Orange card holders without income support.', 'Low $7.00, high $14.00 a fortnight', 364, '1 Jul to 19 Sep 2026', 'Paid automatically by DVA.', null, 'https://www.dva.gov.au/financial-support/payment-rates/summary-pension-rates-limits-and-allowances', 'Eligibility from clik.dva.gov.au/node/16577. Rate may have changed 20 Sep 2026.'),
('FED-033', 'War Widow(er)''s Pension', 'Department of Veterans'' Affairs', 'Federal', 'ALL', 'Payments', 'A pension for widows and widowers of veterans whose death was war-caused (existing recipients).', array['DVA_GOLD']::text[], null, array['veteran']::text[], array[]::text[], false, 'Existing recipients; closed to new claims under the VEA from 1 July 2026.', '$1,223.40 a fortnight (incl. Energy Supplement)', 31808.4, '1 Jul to 19 Sep 2026', 'Existing recipients paid automatically.', null, 'https://www.dva.gov.au/financial-support/payment-rates/summary-pension-rates-limits-and-allowances', 'VEA closed to new claims 1 Jul 2026; new claims under MRCA - check. Rate may have changed 20 Sep 2026.'),
('FED-034', 'DVA funeral benefit', 'Department of Veterans'' Affairs', 'Federal', 'ALL', 'Payments', 'Help with funeral costs for eligible veterans.', array['DVA_GOLD','DVA_WHITE']::text[], null, array['veteran']::text[], array[]::text[], true, 'Eligible veterans'' estates/family as set by DVA.', 'Up to $2,000', null, '1 Jul to 19 Sep 2026', 'Claim through DVA.', null, 'https://www.dva.gov.au/financial-support/payment-rates/summary-pension-rates-limits-and-allowances', 'One-off. Eligibility rules not on fetched page.'),
('NSW-001', 'Low Income Household Rebate', 'NSW Government (via electricity retailer)', 'State', 'NSW', 'Bills', 'A yearly discount on your electricity bill if you have a pension or health care card.', array['PCC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Electricity account in your name for your main NSW home, and a Pensioner Concession Card (Services Australia or DVA), Health Care Card, Low Income Health Care Card or DVA Gold Card. Commonwealth Seniors Health Card holders are not eligible. One per household per year; cannot also get the Seniors Energy Rebate.', '$285 a year off your electricity bill', 285, '2025-26', 'Retail customers phone their electricity retailer with their CRN or DVA file number. Embedded network (on-supply) customers apply online or by post via Service NSW.', '13 77 88', 'https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf', 'Amount from the 2025-26 partner toolkit; Service NSW apply pages (Oct 2026) do not state the 2026-27 amount. Service NSW on-supply page: https://www.service.nsw.gov.au/transaction/apply-low-income-household-rebate'),
('NSW-002', 'Seniors Energy Rebate', 'NSW Government', 'State', 'NSW', 'Bills', 'A yearly payment towards your electricity bill if you hold a Commonwealth Seniors Health Card.', array['CSHC']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Electricity account in your name for your NSW home and a current Commonwealth Seniors Health Card (Services Australia or DVA). Not available if you hold a Pensioner Concession Card or Veteran Gold Card. One per household per year, and not as well as the Low Income Household Rebate.', '$200 a year towards your electricity bill', 200, '2025-26', 'Apply online through the Social Programs for Energy portal via Service NSW, or post the paper form with your latest bill to NSW Energy Rebates, PO Box 435, Parramatta NSW 2124. Must be re-claimed each financial year.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-for-the-seniors-energy-rebate', '$200 figure is from the 2025-26 toolkit (https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf); the Service NSW page is taking 2026-27 applications but does not show the amount.'),
('NSW-003', 'Medical Energy Rebate', 'NSW Government (via electricity retailer)', 'State', 'NSW', 'Bills', 'A yearly electricity discount if you or someone at home cannot control body temperature because of a medical condition.', array['PCC','HCC','DVA_GOLD']::text[], null, array['electricity_account','medical_condition']::text[], array[]::text[], true, 'Electricity account in your name; Pensioner Concession Card, Health Care Card, Low Income Health Care Card or DVA Gold Card; you or a household member cannot self-regulate body temperature, assessed by a GP or specialist who has treated them for at least 3 months, and meets a primary and secondary qualifying condition.', '$285 a year off your electricity bill', 285, '2025-26', 'Download the form from Service NSW, have your doctor complete it, and give it to your electricity retailer. Embedded network customers apply online or at a Service NSW Centre.', '13 77 88', 'https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf', 'Qualifying conditions are not listed in the toolkit.'),
('NSW-004', 'Life Support Rebate', 'NSW Government (via electricity retailer)', 'State', 'NSW', 'Bills', 'Help with electricity costs if you or someone at home uses approved life support equipment such as home dialysis, a ventilator or oxygen concentrator.', array['NONE']::text[], null, array['electricity_account','life_support']::text[], array[]::text[], true, 'Electricity account in your name for your main NSW home; you or someone living with you has been assessed by a registered medical practitioner as needing approved life support equipment at home. No concession card required.', 'Up to $1,343 a year depending on the equipment', 1343, '2025-26', 'Download the form from Service NSW, have your doctor complete it, and submit through your electricity retailer. Embedded network customers apply online or by post via Service NSW.', '13 77 88', 'https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf', 'Amount varies by equipment type.'),
('NSW-005', 'NSW Gas Rebate', 'NSW Government (via gas retailer)', 'State', 'NSW', 'Bills', 'A yearly discount on your natural gas or bottled LPG bill if you have a pension or health care card.', array['PCC','HCC','DVA_GOLD']::text[], null, array['gas_account']::text[], array[]::text[], true, 'Natural gas or bottled LPG (over 45 kg / 88 litres) account in your name for your main NSW home and a Pensioner Concession Card, Health Care Card, Low Income Health Care Card or DVA Gold Card. CSHC holders are not eligible.', '$110 a year off your gas bill', 110, '2025-26', 'Retail customers phone their gas retailer with their CRN or DVA file number. Embedded network and bottled LPG customers apply online or by post via Service NSW.', '13 77 88', 'https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf', 'Retail apply page: https://www.service.nsw.gov.au/transaction/apply-for-the-gas-rebate-retail-customers'),
('NSW-006', 'Energy Accounts Payment Assistance (EAPA)', 'NSW Government (via community welfare providers)', 'State', 'NSW', 'Bills', 'Emergency vouchers to help pay an overdue electricity or gas bill when you are in short-term financial crisis.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Electricity or natural gas account in your name for your main NSW home; most recent bill unpaid and account open; experiencing short-term financial hardship, crisis or emergency.', 'Up to $1,600 (max 2 applications); electricity and gas each capped at $400 per application', null, '2025-26', 'Apply online through Service NSW, or in person or by phone with one of 200+ approved EAPA community providers.', '13 77 88', 'https://www.energy.nsw.gov.au/sites/default/files/2025-07/20250730-Energy-rebates-partner-toolkit-2025-26.pdf', 'Toolkit says ''up to $1,600, with a maximum of 2 applications''; annual cap period not stated clearly, so max_annual_value left null.'),
('NSW-007', 'Pensioner council rates rebate', 'NSW Government and local council', 'Council', 'NSW', 'Home and Rates', 'A yearly discount on your council rates and waste charges if you are a pensioner who owns your home.', array['PCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Pensioner Concession Card; DVA Gold Card embossed TPI or EDA; or war widow/widower or wholly dependent partner receiving DVA income support supplement that attracts a PCC. Rebates may also be granted in some hardship cases.', 'Up to $250 a year off ordinary council rates and domestic waste charges', 250, '2025-26 (statutory amount)', 'Check your rates notice first; if not applied, get the pensioner rebate form from your council''s website and submit it with your card details.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-council-rates-rebate', 'Funded 55% NSW Government / 45% council (per NSW media release 24 Aug 2023: https://www.nsw.gov.au/media-releases/concessions-now-available-to-pensioners-for-council-rates). Some councils add extra voluntary rebates. DVA Gold eligibility limited to TPI/EDA.'),
('NSW-008', 'Pensioner council water and sewer rebate', 'Local council (where council supplies water)', 'Council', 'NSW', 'Home and Rates', 'A yearly discount on council water and sewerage charges for pensioner homeowners.', array['PCC','DVA_GOLD']::text[], null, array['homeowner','water_account']::text[], array[]::text[], true, 'Same cards as the pensioner council rates rebate; only where your council is your water and/or sewerage provider.', 'Up to $87.50 a year off water charges and up to $87.50 a year off sewerage charges', 175, '2025-26 (statutory amount)', 'Apply to your council with its pensioner rebate form, or check your rates notice to see if it is already applied.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-council-rates-rebate', 'If your water is from Sydney Water, Hunter Water, Shoalhaven Water, Essential Water or a private scheme, see those separate rebates instead (https://www.service.nsw.gov.au/transaction/claim-the-pensioner-water-rebate).'),
('NSW-009', 'Sydney Water pensioner rebate', 'Sydney Water', 'State', 'NSW', 'Home and Rates', 'A discount on Sydney Water fixed water, wastewater and stormwater charges for pensioner homeowners.', array['PCC','DVA_GOLD']::text[], null, array['homeowner','water_account']::text[], array[]::text[], true, 'Pensioner Concession Card (Services Australia or DVA) or Veteran Gold Card marked War Widow/Widower, EDA, TTI or TPI; or DVA Disability Compensation Payment at TTI or Intermediate rate. Must own (or be life tenant etc.) and live in the property. CSHC, Health Care Card, Veteran White and Orange cards not eligible.', 'Up to $26.65 water + $144.56 wastewater + $13.68 stormwater (house) per quarter; Sydney Water''s example is about $679.20 a year', null, 'Year not stated on page', 'Apply online with Sydney Water''s pension rebate form (one form per pensioner owner), or phone if you are a DVA payment recipient without a Gold Card.', '13 20 92', 'https://www.sydneywater.com.au/accounts-billing/managing-your-account/pension-rebates/claim-your-pensioner-rebate.html', 'Quarterly maxima are for a 92-day quarter; amount reduced for some co-owner arrangements. Annual maximum not stated, so null.'),
('NSW-010', 'Hunter Water pension rebate', 'Hunter Water', 'State', 'NSW', 'Home and Rates', 'A yearly discount on Hunter Water bills for pensioners who own and live in their home.', array['PCC','DVA_GOLD']::text[], null, array['homeowner','water_account']::text[], array[]::text[], true, 'Own and live in a residential property (main home) and hold a Pensioner Concession Card or DVA Gold Card. Tenants generally not eligible except life tenancy or sole beneficiary.', 'Up to $445 a year for water and sewer ($222.50 for water only)', 445, 'Current (year not stated)', 'Complete the pension rebate form on the Hunter Water website, or use online chat.', '1300 657 657', 'https://hunterwater.com.au/accounts-and-billing/get-help-paying/pension-rebate', null),
('NSW-011', 'NSW Private Water Scheme Pensioner Rebate', 'NSW Department of Climate Change, Energy, the Environment and Water', 'State', 'NSW', 'Home and Rates', 'A yearly rebate on water and wastewater fixed charges for pensioners served by a licensed private water scheme.', array['PCC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'Pensioner Concession Card (Services Australia or DVA), DVA Gold Card marked War Widow/Widower, EDA, TTI or TPI, or DVA intermediate rate pension; water bill from an eligible private scheme (e.g. Central Park Water, Huntlee Water) in your name. CSHC holders not eligible.', 'Up to $592.43 a year ($97.20 drinking water + $495.23 wastewater fixed charges)', 592.43, '2025-26', 'Complete the application form, attach a 2025-26 bill and email to private.water.rebates@pwr.planning.nsw.gov.au or post to PO Box 435, Parramatta NSW 2124 by 30 June 2026.', '(02) 3816 2771', 'https://www.water.dcceew.nsw.gov.au/sites/default/files/2025-09/private-water-rebate-scheme-pensioner-rebate-application-form-2025-26.pdf', '2026-27 form not checked; 2025-26 deadline was 30 June 2026.'),
('NSW-012', 'NSW Seniors Card', 'NSW Government', 'State', 'NSW', 'Discounts', 'A free card for NSW residents aged 60+ who work 20 hours a week or less, giving business discounts and access to Gold Opal $2.50 travel.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or over (or turning 60 within 3 weeks), NSW resident, Australian citizen or permanent resident, not working or averaging 20 hours or less paid work a week over 12 months.', 'Free; discounts at participating businesses and access to Gold Opal fares', null, 'Current', 'Apply online with a MyServiceNSW Account, in person at Service NSW, or by phone. Card arrives by post in about 21 days; digital card available in the Service NSW app.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-for-a-nsw-seniors-card-or-nsw-senior-savers-card', null),
('NSW-013', 'NSW Senior Savers Card', 'NSW Government', 'State', 'NSW', 'Discounts', 'A free discount card for NSW residents aged 60+ who still work more than 20 hours a week.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or over, NSW resident, Australian citizen or permanent resident, averaging more than 20 hours paid work a week over 12 months.', 'Free; discounts at participating businesses (no Gold Opal or transport concessions)', null, 'Current', 'Apply online, in person or by phone through Service NSW; can be converted to a Seniors Card if work hours drop.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-for-a-nsw-seniors-card-or-nsw-senior-savers-card', null),
('NSW-014', 'Gold Senior/Pensioner Opal fares', 'Transport for NSW', 'State', 'NSW', 'Transport', 'Unlimited public transport across Sydney and Opal networks for no more than $2.50 a day.', array['SENIORS_CARD','PCC']::text[], null, array[]::text[], array[]::text[], true, 'NSW or ACT Seniors Card holders (or interstate seniors card if you live outside NSW/ACT); Transport for NSW also offers Gold Opal to eligible Australian pensioners, war widows/widowers and asylum seekers.', 'Maximum $2.50 a day on Opal public transport', null, 'Current', 'Apply for a Gold Opal card through Transport for NSW, or link your concession entitlement to a credit/debit card to tap on and off.', '13 77 88', 'https://www.service.nsw.gov.au/transaction/apply-for-a-gold-senior-pensioner-opal-card', 'Service NSW lists only Seniors Cards as qualifying; transportnsw.info/pensioners says pensioners qualify but does not name the exact card. Senior Savers Card holders not eligible.'),
('NSW-015', 'Pensioner Travel Vouchers', 'Transport for NSW (NSW TrainLink)', 'State', 'NSW', 'Transport', 'Four free regional train or coach trips a year for pensioners.', array['PCC']::text[], null, array[]::text[], array[]::text[], true, 'NSW/ACT Pensioner Concession Card holders and NSW War Widow/er transport concession card holders.', '4 vouchers per calendar year (2 return or 4 single economy trips) on NSW TrainLink Regional services', null, 'Calendar year', 'Book through NSW TrainLink and carry your concession card when travelling. First class upgrade costs 15% of full adult peak fare.', '13 22 32', 'https://www.service.nsw.gov.au/referral/use-your-concession-card-to-access-pensioner-travel-vouchers', 'Phone is NSW TrainLink general line, not shown on the source page; verify.'),
('NSW-016', 'Country Pensioner Excursion (CPE) ticket', 'Transport for NSW (NSW TrainLink)', 'State', 'NSW', 'Transport', 'Cheap day trips on regional train and coach services for eligible pensioners and seniors.', array['PCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Eligible pensioners and seniors (source does not spell out cards).', '$2.50 ticket', null, 'Current', 'Ask a NSW TrainLink sales agent.', null, 'https://transportnsw.Info/travel-in-regional-nsw-for-seniors-pensioners-concessions', 'Card eligibility not confirmed on source; Service NSW Gold Opal page also mentions CPE for PCC and Seniors Card holders.'),
('NSW-017', 'Pensioner vehicle registration concession', 'Transport for NSW', 'State', 'NSW', 'Transport', 'Free car registration and motor vehicle tax for one vehicle if you have a Pensioner Concession Card.', array['PCC','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'NSW resident with a Pensioner Concession Card (Services Australia or DVA) showing a NSW address; DVA Gold Card endorsed TPI, EDA or War Widow; or certain DVA disability statements. Interstate cards not accepted. One vehicle per person.', 'Free registration fees and motor vehicle tax (you still pay CTP and safety check)', null, 'Current', 'Checked electronically at renewal; automatic renewal available. Contact Service NSW if eligibility cannot be confirmed. Refunds possible for up to 3 years.', '13 22 13', 'https://www.nsw.gov.au/driving-boating-and-transport/vehicle-registration/renewing-vehicle-registration/pensioner-concessions-and-renewals', 'Dollar value depends on vehicle weight; not stated.'),
('NSW-018', 'Free driver licence, Photo Card and Mobility Parking Permit for pensioners', 'Transport for NSW', 'State', 'NSW', 'Transport', 'Pensioners get free driver licences, driving tests, NSW Photo Cards and Mobility Parking Permits.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Current Pensioner Concession Card (Services Australia or DVA) with a NSW address, or certain DVA Gold Cards/statements. Interstate cards not accepted.', 'Free licence, tests, Photo Card and Mobility Parking Permit', null, 'Current', 'Eligibility is checked electronically at Service NSW; pro-rata refund available if you become a pensioner mid-licence.', '13 22 13', 'https://www.nsw.gov.au/driving-boating-and-transport/driver-and-rider-licences/fees/concessions-and-discounts', null),
('NSW-019', 'Free NSW Photo Card for Seniors Card holders', 'Transport for NSW', 'State', 'NSW', 'Discounts', 'NSW Seniors Card and Senior Savers Card holders can get a NSW Photo Card for free.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'NSW Seniors Card or Senior Savers Card holder (not the other pensioner licence concessions).', 'Free NSW Photo Card', null, 'Current', 'Apply for a Photo Card at Service NSW and show your Seniors Card.', '13 22 13', 'https://www.nsw.gov.au/driving-boating-and-transport/driver-and-rider-licences/fees/concessions-and-discounts', null),
('NSW-020', 'Boat and PWC licence concession', 'Transport for NSW (Maritime)', 'State', 'NSW', 'Transport', 'Half price boat and jet ski licences for pensioners.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'NSW Pensioner Concession Card (Centrelink or DVA), or DVA Gold Card endorsed TPI, EDA or war widow/er (with DVA evidence of disability pension 70%+, intermediate pension or 50+ impairment points).', '50% off licence fees, e.g. 1-year boat licence $41 instead of $82', null, 'Current fee table', 'Contact Transport for NSW Roads and Waterways or a Service NSW centre.', '13 12 36', 'https://www.nsw.gov.au/driving-boating-and-transport/maritime-licences/boat-and-pwc-licences/licence-and-test-fees', null),
('NSW-021', 'Boat registration concession', 'Transport for NSW (Maritime)', 'State', 'NSW', 'Transport', 'Half price boat registration for pensioners.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'NSW Pensioner Concession Card (Centrelink or DVA), or DVA Gold Card endorsed TPI, EDA or war widow/er with qualifying DVA evidence.', '50% off registration and renewal fees, e.g. vessel up to 3m $46 instead of $94', null, 'From 1 July 2026', 'Contact the Maritime Info Line or a Service NSW centre.', '13 12 36', 'https://www.nsw.gov.au/boat-and-vessel-registration/fees-and-concessions', null),
('NSW-022', 'Recreational fishing fee exemption', 'NSW Department of Primary Industries', 'State', 'NSW', 'Discounts', 'Pensioners do not have to pay for a NSW recreational fishing licence.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card (Centrelink or DVA), DVA Gold Card marked TPI or EDA, or DVA letter confirming 70%+ disability payment. Seniors Card, Health Care Card and DVA White Card are not exempt.', 'Free (fishing fee waived)', null, 'Current', 'No form needed; carry your signed card when fishing.', '1300 550 474', 'https://www.dpi.nsw.gov.au/fishing/recreational/recreational-fishing-fee/exemptions', 'CSHC not listed as exempt.'),
('NSW-023', 'Free NSW Ambulance', 'NSW Ambulance', 'State', 'NSW', 'Health', 'Free ambulance treatment and transport in NSW for concession card holders.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Valid Health Care Card, Pensioner Concession Card or Commonwealth Seniors Health Card; DVA Gold Card (excludes non-emergency); DVA White Card only for DVA-funded conditions. Dependants only if Centrelink has verified them.', 'Free ambulance service', null, 'Current', 'No application needed; give your card details if you receive an account, or claim an exemption via Service NSW.', null, 'https://www.ambulance.nsw.gov.au/our-services/accounts-and-fees/exemptions-from-nsw-ambulance-fees', null),
('NSW-024', 'NSW public dental services', 'NSW Health', 'State', 'NSW', 'Health', 'Free dental care at NSW public dental clinics for adults with a concession card.', array['PCC','HCC','CSHC']::text[], null, array[]::text[], array[]::text[], true, 'NSW resident, eligible for Medicare, and holder of (or dependant on) a Health Care Card, Pensioner Concession Card or Commonwealth Seniors Health Card.', 'Free public dental care (waiting lists apply)', null, 'Current', 'Phone the public dental service with your postcode, Medicare details and concession card.', '1800 679 336', 'https://www.health.nsw.gov.au/oralhealth/Pages/info-patients.aspx', 'Dentures not mentioned on the page.'),
('NSW-025', 'NSW Spectacles Program', 'NSW Government (via Vision Australia)', 'State', 'NSW', 'Health', 'Free glasses every two years for people on very low incomes with few assets.', array['PCC','HCC']::text[], null, array['low_income']::text[], array[]::text[], true, 'NSW permanent resident on a full Centrelink pension or income support with no other income (or income below the full Age Pension if 65+); financial assets under $500 single / $1,000 couple; not eligible for DVA or other spectacle subsidies.', 'One free pair of single vision or bifocal glasses every 2 years', null, 'Current', 'Apply through the Service NSW / NSW Spectacles Program page.', null, 'https://www.service.nsw.gov.au/transaction/nsw-spectacles-program', null),
('NSW-026', 'Isolated Patients Travel and Accommodation Assistance Scheme (IPTAAS)', 'NSW Health', 'State', 'NSW', 'Health', 'Help with travel and accommodation costs if you have to travel a long way for specialist medical treatment.', array['NONE']::text[], null, array['rural']::text[], array[]::text[], true, 'Travelling at least 100 km one way (or 200 km a week over multiple trips) to the nearest treatment that is not available locally, with a recognised specialist, approved clinic or clinical trial.', '40c per km by private car; accommodation $75 a night (1-7 nights), $120 a night (8+ nights), $40 a night staying with family/friends', null, 'Current', 'Apply online via the IPTAAS website after treatment, with forms signed by your specialist; air travel needs prior approval.', '1800 478 227', 'https://iptaas.health.nsw.gov.au/for-patients/subsidy-rates', 'Patient contribution amounts for concession vs non-concession not found on opened pages. Eligibility from https://iptaas.health.nsw.gov.au/for-patients/eligibility'),
('NSW-027', 'National Parks Concession Pass', 'NSW National Parks and Wildlife Service', 'State', 'NSW', 'Discounts', 'Free car entry to NSW national parks for pensioners and veterans.', array['PCC','DVA_GOLD','DVA_WHITE']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Australian Pensioner Concession Card holders and Australian veteran card holders. Not for international pensioner or seniors cards.', 'Free vehicle entry to the 45 parks that charge entry fees', null, 'Current', 'Apply online at NSW National Parks, call, or visit a Service NSW centre or NPWS office.', '1300 072 757', 'https://www.nationalparks.nsw.gov.au/passes-and-fees/discount-and-concession-passes', null),
('NSW-028', 'National Parks annual pass seniors discount', 'NSW National Parks and Wildlife Service', 'State', 'NSW', 'Discounts', 'About 20% off NSW national parks annual passes for Seniors Card holders.', array['SENIORS_CARD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Current Australian Seniors Card holder (not Senior Savers Card); vehicle in your name or registered to your address.', 'About 20% off all four annual pass types', null, 'Current', 'Apply online with a photo of your Seniors Card and rego certificate, or call / visit Service NSW.', '1300 072 757', 'https://www.nationalparks.nsw.gov.au/passes-and-fees/discount-and-concession-passes', null),
('NSW-029', 'Toll Relief weekly cap', 'NSW Government (Service NSW)', 'State', 'NSW', 'Transport', 'Money back on toll costs above $50 a week on NSW toll roads.', array['NONE']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Personal toll account and privately registered vehicle; spend more than $50 a week on NSW tolls. Business, employer-reimbursed and rideshare trips excluded.', 'Rebate of toll spend between $50 and $400 a week, up to $350 a week per token and $5,000 a year', 5000, 'From 6 July 2026 (12 months)', 'Link your toll account to MyServiceNSW and claim online once each quarterly claim window opens.', '13 77 88', 'https://service.nsw.gov.au/transaction/claim-the-toll-relief-cap', 'Not seniors-specific. Cap dropped from $60 to $50 on 6 July 2026.'),
('NSW-030', 'Taxi Transport Subsidy Scheme', 'Transport for NSW', 'State', 'NSW', 'Transport', 'Half price taxi fares for people with a severe permanent disability who cannot use public transport.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'NSW resident with a severe, permanent disability (mobility, vision, epilepsy, intellectual, speech or hearing) that prevents using public transport. Not means tested.', '50% of the taxi fare, up to $60 subsidy', null, 'Current', 'Download the form, have your doctor complete parts B and C, and apply online or by post.', '131 500', 'https://www.service.nsw.gov.au/transaction/apply-taxi-transport-subsidy-scheme', 'Source unclear whether $60 is per trip.'),
('NSW-031', 'EnableNSW Aids and Equipment Program', 'NSW Health (EnableNSW)', 'State', 'NSW', 'Health', 'Equipment such as mobility aids, home oxygen and continence products to help you live safely at home.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'NSW residents with specific short-term or ongoing health needs; eligibility criteria and co-payments apply (see EnableNSW eligibility indicator).', 'Aids and equipment provided or funded; co-payment may apply', null, 'Current', 'A health professional (prescriber) applies on your behalf; contact EnableNSW for details.', '1800 362 253', 'https://www.enable.health.nsw.gov.au/', 'Age 65+ interplay with My Aged Care/Support at Home not confirmed on opened page.'),
('NSW-032', 'NSW Companion Card', 'NSW Government', 'State', 'NSW', 'Discounts', 'Free entry for your carer or support person at participating venues and events.', array['NONE']::text[], null, array['carer']::text[], array[]::text[], true, 'Significant and permanent disability, unable to take part in most community activities without lifelong attendant care; Australian citizen or permanent resident living in NSW.', 'Free entry for your support person', null, 'Current', 'Apply online via the nsw.gov.au ''Get a Companion Card'' page with supporting documents.', null, 'https://www.service.nsw.gov.au/referral/apply-for-a-companion-card', '''carer'' tag used to indicate a support person is needed; review.'),
('NT-001', 'NT Concession Scheme membership', 'NT Government (NT Concession and Recognition Unit)', 'State', 'NT', 'Discounts', 'Join this free scheme to unlock NT discounts on power, water, council rates, garbage, rego, licence and glasses.', array['PCC','CSHC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card.', 'Gives access to the NT concessions listed separately', null, 'Ongoing', 'Apply online at ntconcessions.nt.gov.au, or post/email the application form with 100 points of ID; processing takes about 20 working days.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/become-a-member', 'Health Care Card and DVA White Card are not listed as qualifying cards. Age Pension recipients qualify (PCC). All concessions are capped and only one member per household can claim.'),
('NT-002', 'Electricity concession', 'NT Government (via Jacana Energy / Power and Water)', 'State', 'NT', 'Bills', 'Up to $1,200 a year off your home electricity bill.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Must be the primary account holder for your main home (owner or primary tenant for prepaid meters).', 'Up to $1,200 a year (8,000 kWh): $1.274/day plus $0.091/kWh incl GST on Jacana bills', 1200, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Give your NT Concession Scheme membership number to Jacana Energy or Power and Water; caravan park / alternative energy users claim with the form and receipts.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/electricity', 'Prepaid meter users get $600 credited in late January and late July. Caravan park / alternative energy: $1.274 per day unless actual use is shown. No concession if solar covers all use. Cap resets each financial year.'),
('NT-003', 'Electricity medical support allowance', 'NT Government', 'State', 'NT', 'Health', 'Extra $154 if a medical condition pushes your power use over the concession cap.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['electricity_account','medical_condition']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. You have exceeded the electricity cap and you or a dependant has a medical condition that directly affects electricity use; you must pay the account.', '$154 allowance', 154, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Apply using the medical support allowance form to the NT Concession and Recognition Unit.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/electricity', 'Page does not mention life support equipment specifically.'),
('NT-004', 'Water concession', 'NT Government (via Power and Water)', 'State', 'NT', 'Bills', 'Up to $800 a year off your home water bill.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Primary account holder or financially responsible for water at your main home (units/townhouses: titleholder or financially responsible; retirement villages: lifetime occupancy).', 'Up to $800 a year: $0.96/day plus $0.955/kL (471 kL)', 800, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Houses: give your membership number to Power and Water. Units, retirement villages and water carting: email ntconcessionandrecognition@nt.gov.au or visit a customer service centre with proof of payment and vendor form.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/water-and-sewerage', 'Unit/townhouse/retirement village claims reimbursed around January and July. Remote water carting: $0.955/kL. One concession per household.'),
('NT-005', 'Sewerage concession', 'NT Government (via Power and Water)', 'State', 'NT', 'Bills', 'Up to $486.12 a year off sewerage charges.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Financially responsible for sewerage charges at your main home.', 'Up to $486.12 a year ($1.332 a day)', 486.12, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Houses: give your membership number to Power and Water; others email ntconcessionandrecognition@nt.gov.au or visit a customer service centre.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/water-and-sewerage', null),
('NT-006', 'Council rates concession', 'NT Government (via local council)', 'State', 'NT', 'Home and Rates', '62.5% off your council rates, up to $200 a year.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Registered titleholder responsible for rates on your principal place of residence; one property per rating year.', '62.5% of annual rates, up to $200 a year per household', 200, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'First claim: email ntconcessionandrecognition@nt.gov.au or visit a customer service centre with your rates invoice, proof of payment and vendor creation form; after that the council applies it automatically.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/council-rates-and-garbage', 'Claim within 6 months of the cost or within the financial year, whichever is greater.'),
('NT-007', 'Garbage concession', 'NT Government (via local council)', 'State', 'NT', 'Home and Rates', 'Discount on council garbage charges, up to $150 a year depending on where you live.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Titleholder of the home you live in and responsible for council or body corporate garbage charges; properties outside town/shire areas and private collections excluded.', 'Darwin $46.25, Palmerston $47.50, Alice Springs $52, Katherine $45, Tennant Creek $45, up to $150 (Wagait) a year', 150, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Claim with the council rates concession: email ntconcessionandrecognition@nt.gov.au or visit a customer service centre.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/council-rates-and-garbage', 'Amount varies by council (17 listed, $10.37 Mataranka to $150 Wagait).'),
('NT-008', 'Free driver licence renewal', 'NT Government (Motor Vehicle Registry)', 'State', 'NT', 'Transport', 'Renew your NT driver licence for free.', array['PCC','CSHC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card.', 'Free licence renewal', null, 'Ongoing', 'Give your NT Concession Scheme membership number at an MVR office when renewing.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/driver-licence-and-vehicles', 'Fee saved not stated on the source.'),
('NT-009', 'Vehicle registration concession', 'NT Government (Motor Vehicle Registry)', 'State', 'NT', 'Transport', 'Up to $154 a year off registering your car, motorbike or mobility scooter.', array['PCC','CSHC','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card. Non-commercial vehicle, motorcycle, motorised wheelchair or trike; not company vehicles, caravans or trailers.', 'Up to $154 for 12 months ($77 for 6 months)', 154, '2026-27 (page updated 31 Jul 2026; year not stated on page)', 'Give your membership number at MVR when renewing registration.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/driver-licence-and-vehicles', 'Annual cycle runs from your concession anniversary.'),
('NT-010', 'Spectacles concession', 'NT Government (via approved optometrists)', 'State', 'NT', 'Health', 'Up to $502.20 towards prescription glasses or contact lenses every two years.', array['PCC','CSHC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'NT Concession Scheme member: NT resident at least 183 days of the financial year, Australian citizen or permanent resident, receiving Age Pension, Disability Support Pension, Carer Payment or Parenting Payment (single), or holding a DVA Gold Card, DVA orange card, Pensioner Concession Card or Commonwealth Seniors Health Card.', 'Up to $502.20 every 2 years (about $251 a year)', 251.1, 'Page updated 4 Nov 2024', 'Claim at the time of purchase from an approved optometrist (listed for Darwin, Palmerston, Katherine and Alice Springs).', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-concession-scheme/concessions/spectacles', 'max_annual_value is $502.20 halved. Covers bifocals/multifocals or reading+distance pair or contacts, plus tinting and repairs.'),
('NT-011', 'NT Seniors Recognition Scheme prepaid card', 'NT Government (NT Concession and Recognition Unit)', 'State', 'NT', 'Payments', 'A $550 prepaid card every financial year for Territorians aged 65+, to spend as you choose.', array['NONE']::text[], null, array['aged_65']::text[], array[]::text[], true, 'Aged 65 or over; NT resident at least 183 days of the financial year; Australian citizen, permanent resident or temporary visa holder with Medicare card at an NT address.', '$550 per financial year on a prepaid card', 550, 'Per financial year (page current 2026)', 'Apply online at ntconcessions.nt.gov.au or by form with 100 points of ID; apply by 1 May to get that financial year''s card.', '1800 777 704', 'https://nt.gov.au/community/concessions-and-payments/nt-seniors-recognition-scheme', 'DVA factsheet says $500 (older figure); nt.gov.au says $550. Restricted merchant categories apply.'),
('NT-012', 'NT Seniors Card', 'COTA NT for NT Government', 'State', 'NT', 'Discounts', 'Free card for Territorians 60+ giving discounts at participating businesses.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Permanent NT resident aged 60 or over.', 'Free; discounts vary by business', null, 'Ongoing', 'Post the Seniors Card application form to Seniors Card, GPO Box 852, Darwin NT 0801.', '1800 441 489', 'https://nt.gov.au/community/seniors/apply-for-seniors-card', 'No work-hours test mentioned. Card does not need renewing. [Claude: cards set to NONE so people without the card are told about it.]'),
('NT-013', 'Seniors Card vehicle registration concession', 'NT Government (Motor Vehicle Registry)', 'State', 'NT', 'Transport', '$55 a year off private car registration for Seniors Card holders.', array['SENIORS_CARD']::text[], null, array['car_owner','aged_60']::text[], array[]::text[], true, 'NT Seniors Card holder (60+) with a private vehicle; card registered with MVR.', '$55 a year off private vehicle registration', 55, 'Ongoing', 'Register your Seniors Card with MVR.', '1800 441 489', 'https://nt.gov.au/community/seniors/apply-for-seniors-card', 'Concession scheme page calls it an ''additional'' Senior''s discount, so may stack with NT-009.'),
('NT-014', 'Seniors Card interstate public transport discounts', 'Interstate transport operators', 'State', 'NT', 'Transport', 'Your NT Seniors Card gets discounted fares on most interstate public transport.', array['SENIORS_CARD']::text[], null, array['aged_60']::text[], array[]::text[], true, 'NT Seniors Card holder.', 'Discounted fares; varies by state', null, 'Ongoing', 'Show your NT Seniors Card; check with the operator before travelling.', '1800 441 489', 'https://nt.gov.au/community/seniors/apply-for-seniors-card', 'No interstate airfare concession found in the current NT scheme.'),
('NT-015', 'Free public bus travel', 'NT Government', 'State', 'NT', 'Transport', 'All public buses in Darwin, Palmerston and Alice Springs are free.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'Anyone; no card mentioned.', 'Free fares', null, 'From 1 July 2025', 'Just board the bus.', null, 'https://nt.gov.au/driving/public-transport-cycling/public-buses/fares', 'Page dated 9 Jul 2025 says ''continue to be free from 1 July 2025''; confirm still current. DVA factsheet also says Gold Card holders get fully subsidised urban bus travel.'),
('NT-016', 'Senior, pensioner and carer stamp duty concession', 'Territory Revenue Office', 'State', 'NT', 'Home and Rates', 'Up to $10,000 off stamp duty when buying a home if you are 60+ or a concession card holder.', array['NONE']::text[], null, array['aged_60']::text[], array[]::text[], true, 'Aged 60 or over, or hold an NT Pensioner and Carer Concession card; not means tested; home dutiable value up to $750,000 (land up to $385,000); must live in it.', 'Up to $10,000 off stamp duty (one-off)', null, 'Page updated 27 Apr 2018', 'Lodge the application form via your conveyancer before settlement, or with the Territory Revenue Office after paying duty.', '1300 305 353', 'https://nt.gov.au/property/homeowner-incentives/seniors,-pensioners-and-carers/senior,-pensioner-and-carer-concession', 'One-off, so max_annual_value null. Concession card holders under 60 also qualify; the ''cards'' field lists NONE because age 60 alone qualifies. Page last updated 2018: thresholds should be checked.'),
('NT-017', 'Free public dental care', 'NT Health', 'State', 'NT', 'Health', 'Free public dental care for adults with a pension, health care or seniors health card.', array['PCC','HCC','CSHC','DVA_GOLD','DVA_WHITE']::text[], null, array[]::text[], array[]::text[], true, 'Holder or dependant of a Pensioner Concession Card, Health Care Card, Commonwealth Seniors Health Card, or DVA Gold or White card.', 'Free', null, 'Ongoing', 'Phone Oral Health Services to book: Darwin 08 8922 6466, Alice Springs 08 8951 6713.', '08 8922 6466', 'https://nt.gov.au/wellbeing/allied-health/public-dental-services/eligibility-for-public-dental-services', '''Free'' wording from https://nt.gov.au/wellbeing/hospitals-health-services/dental-services; eligibility page does not list fees.'),
('NT-018', 'Patient Assistance Travel Scheme (PATS)', 'NT Health', 'State', 'NT', 'Health', 'Help with travel and accommodation costs if you live over 75 km from the specialist you are referred to.', array['NONE']::text[], null, array['rural']::text[], array[]::text[], true, 'Australian citizen or permanent resident living in the NT 6+ months, Medicare enrolled, referred to the nearest approved specialist more than 75 km away (renal/oncology: over 250 km a week).', 'Accommodation $90/night commercial ($60 hostel/not-for-profit, $20 with friends/family); private car 40c/km; air and bus at best fare of the day', null, 'Page modified 26 Feb 2026', 'Your doctor or health provider applies; the hospital patient travel office books travel.', '08 8922 8135', 'https://nt.gov.au/wellbeing/health-subsidies-support-and-home-visits/patient-assistance-travel-scheme/what-you-can-claim-for', 'Other offices: Alice Springs 08 8951 7846, Katherine 08 8973 9215, Tennant Creek 08 8962 4647, Gove 08 8987 0201. Value depends on travel.'),
('NT-019', 'Emergency ambulance cover for concession card holders', 'St John Ambulance NT', 'State', 'NT', 'Health', 'Pensioner Concession Card or Health Care Card holders may have emergency ambulance cover in the NT.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'NT holders of a Centrelink Pensioner Concession Card or Health Care Card may have cover; may not apply in Queensland or South Australia.', 'Emergency ambulance transport (may be free)', null, 'Ongoing', 'Ask St John NT accounts team to confirm your cover.', '08 8922 6200', 'https://www.stjohnnt.org.au/ambulance-services/emergency-ambulance-transport-cover', 'Source wording is ''may have''; DVA factsheet says free emergency ambulance transport for NT PCC holders. Needs checking.'),
('NT-020', 'Taxi Transport Subsidy Scheme', 'NT Government', 'State', 'NT', 'Transport', 'Half-price taxi and minibus fares if a long-term disability stops you using public transport.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'NT resident with a permanent or long-term (6+ months) disability confirmed by a health professional that stops you safely using public transport.', '50% of taxi or minibus fare', null, 'Page modified 30 Jul 2026', 'Complete the TSS form (Part B by your health professional) with photos and proof of residency; mail to GPO Box 2520, Darwin NT 0801 or email cpv.admin@nt.gov.au.', '08 8924 7229', 'https://nt.gov.au/driving/public-transport-cycling/taxi-subsidy-scheme', 'Wheelchair users also covered by the Lift Incentive Scheme ($30 paid to driver per accessible trip).'),
('NT-021', 'Jacana Energy Stay Connected hardship program', 'Jacana Energy (NT Government owned)', 'State', 'NT', 'Bills', 'Help to keep your power on with payment plans if you are struggling to pay.', array['NONE']::text[], null, array['electricity_account','hardship']::text[], array[]::text[], true, 'Jacana customer in financial difficulty, willing to set up a payment arrangement and work with support agencies.', 'Payment plans, extensions and hardship support', null, 'Ongoing', 'Call Jacana Energy or apply online for a payment extension or arrangement.', '1800 522 262', 'https://jacanaenergy.com.au/support/financial-support', 'Not a cash rebate.'),
('NT-022', 'Power and Water Bill Relief Program', 'Power and Water Corporation', 'State', 'NT', 'Bills', 'Interest-free payment plans and no late fees if you are struggling with your water bill.', array['NONE']::text[], null, array['water_account','hardship']::text[], array[]::text[], true, 'Residential customer finding it hard to pay, identified by a financial counsellor, overdue on 2+ bills, or an unusually high bill from a leak.', 'Interest-free plans; no late fees, restrictions or debt collection while on plan', null, 'Ongoing', 'Contact Power and Water customer service.', '1800 245 092', 'https://powerwater.com.au/customer-hardship', 'Not a cash rebate.'),
('QLD-001', 'Electricity Rebate', 'Qld Government (via electricity retailer)', 'State', 'QLD', 'Bills', 'A yearly rebate of about $399 off your home electricity bill.', array['PCC','HCC','SENIORS_CARD','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Queensland Seniors Card, Pensioner Concession Card (Services Australia or DVA), Health Care Card or Veteran Gold Card. Must be the electricity account holder at your principal place of residence; one rebate per household. CSHC holders are not eligible.', '$399.47 a year (GST inclusive)', 399.47, 'Current rate (page updated 10 Jul 2026)', 'Phone your electricity retailer with your concession card; it is then deducted from your bills.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/energy-concessions/electricity-gas-rebates', 'Page does not name the rebate year. Commonwealth Seniors Health Card on its own does not qualify (Qld Seniors Card does).'),
('QLD-002', 'Reticulated Natural Gas Rebate', 'Qld Government (via gas retailer)', 'State', 'QLD', 'Bills', 'A yearly rebate of about $96 off your piped natural gas bill.', array['PCC','SENIORS_CARD','DVA_GOLD']::text[], null, array['gas_account']::text[], array[]::text[], true, 'Queensland Seniors Card, Pensioner Concession Card or Veteran Gold Card (Health Care Card is electricity-only). Must be the gas account holder at your principal place of residence.', '$96.45 a year (GST inclusive)', 96.45, 'Current rate (page updated 10 Jul 2026)', 'Contact your gas retailer; the rebate is deducted from your bills.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/energy-concessions/electricity-gas-rebates', 'Not for bottled LPG.'),
('QLD-003', 'Electricity and Gas Rebates for Home Park and Multi-Unit Residents', 'Qld Government (via park owner/proprietor)', 'State', 'QLD', 'Bills', 'If your power comes through a park, village or unit-complex owner, you still get the rebate as a daily amount.', array['PCC','HCC','SENIORS_CARD','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Residents of residential parks, multi-unit complexes, granny flats etc. who are billed by a proprietor and hold a Qld Seniors Card, PCC, Health Care Card (electricity only) or Veteran Gold Card. Principal place of residence only; not nursing homes, motels or dormitories.', 'Electricity $1.0945 a day (incl GST); gas $0.2643 a day (incl GST)', null, 'Current gazetted daily rate', 'Ask your park owner or proprietor to add you to their Form 502 application to the energy retailer.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/energy-concessions/residential-homes-rebates', 'Daily electricity rate works out to about $399 a year; you do not hold the account yourself, so ''electricity_account'' is approximate.'),
('QLD-004', 'Home Energy Emergency Assistance Scheme (HEEAS)', 'Qld Government (paid to energy retailer)', 'State', 'QLD', 'Bills', 'One-off help of up to $720 to pay an electricity or gas bill after an emergency or money crisis.', array['PCC','HCC','SENIORS_CARD','DVA_GOLD','CSHC','NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Responsible for the overdue bill and hold a concession card, or have income at or below the part-age-pension limit, or be on your energy retailer''s hardship program; plus a big drop in income or high unexpected essential costs in the last 12 months.', 'Up to $720, once every 2 years', null, 'Current', 'Ask your energy retailer for an assessment and application number, then apply online at heeas-application-form.treasury.qld.gov.au.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/energy-concessions/home-energy-emergency-assistance-scheme', 'One-off payment so max_annual_value is null. Card list is broad because the page says ''a current concession card'' or income test.'),
('QLD-005', 'Medical Cooling and Heating Electricity Concession Scheme', 'Qld Government', 'State', 'QLD', 'Bills', 'About $522 a year towards power bills if a medical condition means you must heat or cool your home.', array['PCC','HCC']::text[], null, array['electricity_account','medical_condition']::text[], array[]::text[], true, 'PCC (Services Australia or DVA) or Health Care Card; financially responsible for the electricity bill; a specialist certifies a condition such as MS, autonomic dysfunction, loss of sweating capacity or temperature hypersensitivity.', '$522.09 a year (incl GST), paid quarterly to your bank', 522.09, 'From 1 July 2026', 'Fill in the MCHECS form with your specialist and post it.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/medical-concessions/medical-cooling-heating-electricity-concession-scheme', null),
('QLD-006', 'Electricity Life Support Concession (Oxygen Concentrator)', 'Qld Government', 'State', 'QLD', 'Bills', 'About $1,063 a year towards the power used by a home oxygen concentrator.', array['PCC','HCC','SENIORS_CARD']::text[], null, array['life_support','electricity_account']::text[], array[]::text[], true, 'Oxygen concentrator supplied free through the Medical Aids Subsidy Scheme, and hold a Pensioner Concession Card, Health Care Card or Queensland Seniors Card.', '$1,063.30 a year per machine, paid quarterly', 1063.3, 'From 1 July 2025', 'Complete the form MASS sends within 14 working days of getting the machine.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/medical-concessions/electricity-life-support', 'Page shows 1 July 2025 rates; 2026-27 rate not shown.'),
('QLD-007', 'Electricity Life Support Concession (Kidney Dialysis)', 'Qld Government', 'State', 'QLD', 'Bills', 'About $712 a year towards the power used by a home kidney dialysis machine.', array['NONE']::text[], null, array['life_support','electricity_account']::text[], array[]::text[], true, 'Home dialysis machine supplied free by a Queensland Health hospital. No concession card requirement is listed.', '$712.07 a year per machine, paid quarterly', 712.07, 'From 1 July 2025', 'Complete the form from your hospital Renal Unit.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/medical-concessions/electricity-life-support', null),
('QLD-008', 'Pensioner Rate Subsidy', 'Qld Government (via local council)', 'State', 'QLD', 'Home and Rates', '20% off your council rates, up to $200 a year.', array['PCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Pensioner Concession Card (Services Australia or DVA) or DVA Gold Card; owner or life tenant of your principal place of residence in Qld and legally responsible for the rates.', '20% of gross rates and charges, up to $200 a year', 200, 'Current', 'Apply through your local council.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/property-concessions/rates-subsidy', 'Many councils add their own extra pensioner rebate; not covered here.'),
('QLD-009', 'South East Queensland Pensioner Water Subsidy', 'Qld Government (via water retailer)', 'State', 'QLD', 'Bills', 'Up to $120 a year off water charges for pensioner homeowners in South East Queensland.', array['PCC','DVA_GOLD']::text[], null, array['homeowner','water_account']::text[], array[]::text[], true, 'PCC (Centrelink or DVA) or DVA Gold Card; own or have a life tenancy in your principal place of residence in the SEQ Water Grid and be responsible for rates and charges.', 'Up to $120 a year', 120, 'Current (page last updated 2017)', 'Apply to your water retailer (e.g. Urban Utilities, Unitywater or your council).', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/property-concessions/water-subsidy', 'Page is old (2017); confirm amount with retailer. SEQ only.'),
('QLD-010', 'Emergency Management Levy Concession', 'Qld Government (via council rates)', 'State', 'QLD', 'Home and Rates', '20% off the Emergency Management Levy on your council rates notice.', array['PCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Commonwealth Pensioner Concession Card or Repatriation Health (Gold) Card; principal place of residence.', '20% off the Emergency Management Levy', null, 'Current', 'Ask your local council (often applied with the rates subsidy).', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/property-concessions/emergency-management-levy', 'Dollar value depends on property levy class.'),
('QLD-011', 'Home Assist Secure', 'Qld Government (via local HAS provider)', 'State', 'QLD', 'Home and Rates', 'Help with the labour cost of essential small home repairs and safety jobs, up to $500 a year.', array['PCC']::text[], null, array['aged_60']::text[], array[]::text[], true, 'Aged 60+ (or any age with a disability), hold a Pensioner Concession Card, and unable to do the work yourself. Homeowners and renters. Usually not if you get Commonwealth Home Support or Support at Home.', 'Labour subsidy up to $200 a job and $500 a year (jobs up to $1,500 total)', 500, 'Current', 'Contact your local Home Assist Secure provider (search by suburb or call 13 QGOV); they visit and arrange the work.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/housing/buying-owning-home/homeowners-financial-help/home-assist-secure', 'Smoke alarm $250 component has ended in some areas.'),
('QLD-012', 'Queensland Seniors Card', 'Qld Government', 'State', 'QLD', 'Discounts', 'A free card giving access to state concessions and business discounts for older Queenslanders.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Permanent Qld resident living in Qld 6+ months a year; aged 65+ working under 35 hours a week, or 60-64 working under 35 hours a week and holding a PCC, Health Care Card or DVA Gold/White/Orange card.', 'Free card; unlocks concessions and discounts', null, 'Current', 'Apply online, by phone on 13 QGOV, in person at a Qld Government Service Centre, or by post.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/seniors/legal-finance-concessions/seniors-card/applying-seniors-card', 'Age 60-64 without a card: Seniors Business Discount Card only.'),
('QLD-013', 'Seniors Card +go', 'Qld Government / Translink', 'State', 'QLD', 'Transport', 'Your Seniors Card with a built-in go card for South East Queensland public transport.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Eligible for a Queensland Seniors Card; existing holders can upgrade free.', 'Free upgrade; no $5 deposit (must load $5 credit)', null, 'Current', 'Apply online or call 13 74 68.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/seniors/legal-finance-concessions/seniors-card/seniors-card-types-benefits', null),
('QLD-014', 'Seniors Business Discount Card', 'Qld Government', 'State', 'QLD', 'Discounts', 'A free discount card for Queenslanders aged 60+ who don''t qualify for the full Seniors Card.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or older and a Queensland resident (6+ months a year); not eligible for the Seniors Card.', 'Business discounts and Senior Shopper; no government concessions', null, 'Current', 'Apply through the same Seniors Card application.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/seniors/legal-finance-concessions/seniors-card/applying-seniors-card', null),
('QLD-015', 'Senior Shopper', 'Qld Government (Seniors Card program)', 'State', 'QLD', 'Discounts', 'Free service that finds you a better price on appliances, cars, travel and discounted gift cards.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Holders of a Seniors Card, Seniors Card +go or Seniors Business Discount Card.', 'Free service; gift cards about 2% to 11% off; average 26% saving on electrical goods (program claim)', null, 'Current', 'Register at seniorshopper.com.au and upload your card, then request a quote.', '1300 366 265', 'https://www.qld.gov.au/seniors/legal-finance-concessions/seniors-card/senior-shopper', null),
('QLD-016', 'Seniors Card Interstate and New Zealand Discounts', 'Qld Government / partner businesses', 'State', 'QLD', 'Discounts', 'Use your Qld Seniors Card for business discounts interstate and with New Zealand SuperGold businesses.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Queensland Seniors Card holders.', 'Discounts on request; varies by business', null, 'Current', 'Show your card and ask before purchasing; see the visited state''s Seniors Card site or supergold.govt.nz.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/seniors/legal-finance-concessions/seniors-card/using-seniors-card', 'Government concessions are not included in the NZ arrangement.'),
('QLD-017', 'Translink 50 Cent Fares (Seniors)', 'Translink (Qld Government)', 'State', 'QLD', 'Transport', 'All Translink bus, train, ferry and tram trips cost 50 cents for seniors.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Seniors using a Senior go card or Seniors Card +go; all Translink fares are currently 50 cents for everyone.', '50 cents per journey', null, 'Current', 'Get a Senior go card (show Seniors Card) from a retailer, station or online, or upgrade to Seniors Card +go.', '13 12 30', 'https://translink.com.au/tickets-and-fares/concessions/seniors', '50c fares apply to all passengers now, so the seniors concession adds little on Translink. Regional non-Translink ferries accept any Australian Seniors Card. Gold Coast free bus travel ended 1 July 2025.'),
('QLD-018', 'Brisbane Free Off-Peak Travel for Seniors', 'Brisbane City Council', 'Council', 'QLD', 'Transport', 'Free off-peak trips on Brisbane City Council buses, CityCats and ferries.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Seniors with a Senior go card or Seniors Card +go.', 'Free on Council buses weekdays 8:30am-3:30pm, 7pm-6am and weekends; CityCats/ferries weekdays off-peak only', null, 'Current', 'Touch on and off with your Senior go card.', '13 12 30', 'https://www.brisbane.qld.gov.au/traffic-and-transport/public-transport/free-off-peak-travel-for-seniors', 'Not valid on Queensland Rail trains.'),
('QLD-019', 'Long-Distance Rail Concession (Queensland Rail Travel)', 'Queensland Rail', 'State', 'QLD', 'Transport', 'Up to half off long-distance Queensland Rail trains with a Seniors Card.', array['PCC','SENIORS_CARD','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Australian state Seniors Card (up to 50% off); interstate PCC (25% off); Queensland PCC holders get Queensland pensioner entitlements; Qld resident war widow/er Gold Card holders treated as Qld pensioners.', 'Up to 50% off adult fare (Seniors Card); 25% off (interstate PCC)', null, 'Current', 'Register your card on your Queensland Rail Travel profile then book online, or call.', '1800 872 467', 'https://www.queenslandrailtravel.com.au/Planyourtrip/concession-fares', 'Page does not state the Queensland pensioner discount or any free-trip allowance. Meals and sleeper upgrades not discounted.'),
('QLD-020', 'Vehicle Registration Concession', 'Qld Department of Transport and Main Roads', 'State', 'QLD', 'Transport', 'About half off the registration fee for one car or motorbike.', array['PCC','SENIORS_CARD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Queensland resident with a Qld Seniors Card (not Business Discount Card) or Qld-issued PCC, or ADF member with 70% incapacity / 50 impairment points. One vehicle per person, one per spousal couple, private use, registered in your name.', 'About 50% off the registration fee, e.g. $385.45 to $192.75 for a 4-cylinder car (saves $192.70); CTP and traffic improvement fee not discounted', null, 'Fees as at 1 October 2026', 'Complete form F3937 and email, post or lodge it at a transport customer service centre with a copy of your card.', '13 23 80', 'https://www.qld.gov.au/transport/registration/fees/concession/senior', 'Saving depends on vehicle; fee table at https://www.qld.gov.au/transport/registration/fees/cost. CSHC not listed. DVA Gold Card holders qualify only via TPI/EDA embossing or DVA letter.'),
('QLD-021', 'Boat Registration Concession', 'Qld Department of Transport and Main Roads', 'State', 'QLD', 'Transport', 'Reduced registration fee for one private recreational boat.', array['PCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Queensland resident with Qld Seniors Card or Qld PCC (or prescribed ADF service person); recreational boat in your name; one boat per person, one concession per couple.', 'Reduced registration fee (see fee table)', null, 'Current', 'Complete form F3937 with a copy of your card; applies from the next registration period.', '13 23 80', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/transport-concessions/boat-registration-fees', 'Dollar amount not stated on page.'),
('QLD-022', 'Taxi Subsidy Scheme', 'Qld Department of Transport and Main Roads', 'State', 'QLD', 'Transport', 'Half of your taxi fare paid, up to $30 a trip, if a severe disability stops you using public transport.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Permanent Qld resident who uses a wheelchair, has a severe walking problem, severe vision loss, uncontrolled epilepsy, or dementia/intellectual impairment needing a companion.', '50% of the fare, up to $30 per trip, no trip limit', null, 'Current', 'Complete form QF2330 with a health professional and photo, then email or post to the Taxi Subsidy Unit.', '1300 134 755', 'https://www.qld.gov.au/community/cost-of-living-support/concessions/transport-concessions/taxi-concessions', null),
('QLD-023', 'Free Ambulance for Queensland Residents', 'Queensland Ambulance Service', 'State', 'QLD', 'Health', 'Ambulance treatment and transport is free for Queenslanders, including interstate.', array['NONE']::text[], null, array[]::text[], array[]::text[], true, 'Queensland residents (principal place of residence in Qld) and their dependants.', 'Free; no ambulance cover needed', null, 'Current', 'Nothing to claim. If you get an interstate ambulance bill, follow the Qld interstate ambulance process.', '000 (emergency)', 'https://www.ambulance.qld.gov.au/our-services/emergency-ambulance-response', 'Not limited to pensioners.'),
('QLD-024', 'Public Dental Services', 'Queensland Health', 'State', 'QLD', 'Health', 'Free public dental care for adults with a concession card or Qld Seniors Card.', array['PCC','HCC','CSHC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Queensland residents with a PCC (Centrelink or DVA), Health Care Card, Commonwealth Seniors Health Card or Queensland Seniors Card.', 'Free (you pay your own transport)', null, 'Current', 'Contact your local public dental clinic to check eligibility and join the waiting list.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/health/services/oral-eye-ear/dental-services', 'Waiting lists apply.'),
('QLD-025', 'Spectacle Supply Scheme', 'Queensland Health (MASS)', 'State', 'QLD', 'Health', 'Free basic prescription glasses every two years.', array['PCC','HCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Permanent Qld resident who has held a PCC, Health Care Card or Qld Seniors Card in their own name for 6 months; optometrist confirms your eyesight has changed.', 'Free basic glasses every 2 years', null, 'Current (eligibility page last updated 2018)', 'Ask a participating optometrist; complete the MASS consent form.', '(07) 3136 3636', 'https://www.qld.gov.au/health/condition/eye-health/vision-problems-and-impairments/spectacles-supply-scheme-eligibility', 'Confirm current details; page dated 2018.'),
('QLD-026', 'Medical Aids Subsidy Scheme (MASS)', 'Queensland Health', 'State', 'QLD', 'Health', 'Subsidised mobility, continence, daily-living and other aids for people with a permanent condition.', array['PCC','HCC','SENIORS_CARD']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'Permanent Qld resident with a permanent, stable condition or disability, holding a PCC (Centrelink or DVA), Health Care Card or Qld Seniors Card; clinical assessment by an approved prescriber.', 'Aids on loan or supplied; value varies', null, 'Current', 'A clinician assesses you and applies (MASS-eApply).', '13 QGOV (13 74 68)', 'https://qld.gov.au/seniors/health/illness-support/health-subsidies', 'Card list from seniors health-subsidies page (2017); MASS page itself does not list cards. Copayment rules not confirmed.'),
('QLD-027', 'Patient Travel Subsidy Scheme', 'Queensland Health', 'State', 'QLD', 'Health', 'Help with travel and accommodation costs if you must travel far for specialist treatment.', array['NONE']::text[], null, array['rural']::text[], array[]::text[], true, 'Queensland resident referred to a public specialist service not available locally, more than 50 km from your nearest public hospital.', 'Private car $0.45/km; commercial accommodation up to $70/night; private accommodation $10/night; approved escort may be covered', null, 'Page updated 1 July 2026', 'Register and claim through your local hospital''s PTSS office.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/health/services/travel/subsidies/ptss-subsidies', 'No different rate for concession card holders stated.'),
('QLD-028', 'Stocked Impoundment Permit Concession (Fishing)', 'Qld Department of Primary Industries', 'State', 'QLD', 'Discounts', 'Cheaper annual permit to fish in stocked dams and weirs.', array['PCC','HCC','SENIORS_CARD','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Holders of a Qld Seniors Card, PCC, Health Care Card or Gold Card.', 'Concession annual permit $46.45 (standard $64.58)', null, 'From 1 July 2026', 'Buy online or from a permit agent and enter your card details.', '13 QGOV (13 74 68)', 'https://www.qld.gov.au/recreation/activities/boating-fishing/rec-fishing/dams/stocked-impoundment-permits/buy', 'Queensland has no general recreational fishing licence; this permit is only needed in stocked impoundments. Saving $18.13 a year.'),
('SA-001', 'Cost of Living Concession', 'SA Government (ConcessionsSA)', 'State', 'SA', 'Payments', 'A yearly cash payment into your bank account to help with living costs like council rates and bills.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Live at the property (homeowner, or tenant with a written rental agreement) and hold a Pensioner Concession Card, Commonwealth Seniors Health Card, Low Income Health Care Card, eligible Veteran Gold Card, or get an eligible Centrelink payment, or meet low income limits (single $24,926.20 a year; couple $46,295.60). Assessed on 1 July.', '$270.60 a year, paid by EFT between August and December', 270.6, '2026-27', 'Apply online with the household concessions form at forms.sa.gov.au (or paper form) by 31 December; no need to reapply if nothing has changed.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/cost-of-living-concessions', 'Veteran Gold Card only if TPI, EDA, War Widow or 80+ impairment points (MRCA). Low income provision also allows people with no card. Payment shows as ''SA GOV COLC''.'),
('SA-002', 'Energy Bill Concession', 'SA Government (via energy retailer)', 'State', 'SA', 'Bills', 'Money off your electricity bill each year if you hold a pension or concession card.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Live at the property, energy account in your name and listed first on the bill, and hold a Pensioner Concession Card, Commonwealth Seniors Health Card, Low Income Health Care Card, eligible Veteran Gold Card or an eligible Centrelink payment.', 'Up to $291.27 a year, credited to your bill at a daily rate', 291.27, 'Current figure on page (page updated 1 July 2026, indexed yearly; likely 2026-27)', 'Apply online with the household concessions form or a paper form; you need your CRN or DVA number and latest electricity bill.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/energy-bill-concessions', 'Veteran Gold Card only if TPI, EDA, War Widow or 80+ impairment points (MRCA). Page does not name the financial year. Park residents and people without a retailer bill get quarterly EFT. Also covers LPG/bottled gas users without a retailer bill.'),
('SA-003', 'SA Concessions Energy Discount Offer (Origin)', 'Origin Energy (arranged with SA Government)', 'Private', 'SA', 'Bills', 'If you get the SA energy concession you can switch to an Origin plan with 20% off electricity and 15% off gas.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Only for customers already receiving the SA Government energy concession.', '20% off Origin standard electricity usage and supply, 15% off natural gas, 40% off a 45kg LPG cylinder for 12 months; fee waivers', null, 'Offer runs until at least 2029', 'Phone Origin on 1300 791 465 to sign up; if switching retailer, then call ConcessionsSA so your energy concession follows you.', '1300 791 465', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/energy-bill-concessions/energy-discount-offer', 'Dollar value depends on usage. Savings are provided by Origin, not government. DHS news (2026) confirms it runs until at least 2029.'),
('SA-004', 'Medical Heating and Cooling Concession', 'SA Government', 'State', 'SA', 'Health', 'Extra yearly help with power bills if a doctor says your medical condition needs heating or cooling at home.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array['medical_condition','electricity_account']::text[], array[]::text[], true, 'Clinically verified condition that hot or cold weather severely worsens (certified by GP or specialist), use an air conditioner at home, pay all or part of the energy bill, and hold an eligible concession card or Centrelink payment.', '$291.27 a year, on top of the energy concession', 291.27, 'Current figure on page (page updated 1 July 2026, indexed yearly; likely 2026-27)', 'Complete the form with your doctor and email it to MHC@sa.gov.au.', '1300 735 350', 'https://www.sa.gov.au/topics/care-and-support/concessions/health-concessions/medical-heating-and-cooling-concession', 'Page says ''eligible concession card'' without listing them; assumed same cards as the energy concession. Check.'),
('SA-005', 'Home Dialysis Electricity Concession', 'SA Health', 'State', 'SA', 'Health', 'Yearly payment to help with power costs of running a dialysis machine at home.', array['NONE']::text[], null, array['life_support']::text[], array[]::text[], true, 'Anyone undergoing dialysis treatment at home, approved by an SA Health practitioner.', '$274.85 a year', 274.85, 'Current (year not stated on page)', 'Fill in the Home Dialysis Concession Claim Form with your SA Health practitioner and return it to your renal unit.', '08 8226 6000', 'https://www.sahealth.sa.gov.au/wps/wcm/connect/public+content/sa+health+internet/services/costs+and+concessions/home+dialysis+electricity+concession', 'No card needed per page. Phone is SA Health general line; contact your renal unit.'),
('SA-006', 'Water Rates Concession', 'SA Government (via SA Water or your water provider)', 'State', 'SA', 'Bills', 'Up to 30% off your yearly water bill for pensioners and low-income homeowners and tenants.', array['PCC','HCC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'Own or rent your home, pay for water supply or all usage, and hold a Pensioner Concession Card, Low Income Health Care Card, eligible Veteran Gold Card, eligible Centrelink payment, or meet low income limits.', 'Up to 30% of your water bill: homeowners and tenants paying all water $304.12 to $484.80 a year; tenants paying usage only $197.20 to $377.90', 484.8, '2026-27', 'Apply online with the household concessions form (or paper form). SA Water customers get a bill credit; others get EFT.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/water-and-sewerage-rate-concession', 'Commonwealth Seniors Health Card is NOT listed for this concession. Veteran Gold Card only if TPI, EDA, War Widow or 80+ impairment points (MRCA).'),
('SA-007', 'Sewerage Rates Concession', 'SA Government (via SA Water or council CWMS)', 'State', 'SA', 'Home and Rates', 'Money off sewerage rates on the home you own and live in.', array['PCC','HCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Homeowner-occupier holding a Pensioner Concession Card, Low Income Health Care Card, eligible Veteran Gold Card, eligible Centrelink payment, or meeting low income limits. Tenants are not eligible.', 'Up to $228.12 a year off sewerage rates', 228.12, '2026-27', 'Apply with the household concessions form; SA Water customers get a credit, council CWMS customers get EFT.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/water-and-sewerage-rate-concession', 'CSHC not listed. Veteran Gold Card only if TPI, EDA, War Widow or 80+ impairment points (MRCA).'),
('SA-008', 'Water Concession Top-up Payment', 'SA Government', 'State', 'SA', 'Bills', 'An extra payment if your yearly water bills are very high.', array['PCC','HCC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'Already eligible for the water concession and annual water bills above the threshold: 2026-27 thresholds $1,013.75 (homeowners and tenants paying usage and supply) or $657.35 (tenants paying usage only).', 'Top-up amount depends on bills over the threshold', null, '2026-27 (applications open 1 July 2027)', 'SA Water customers get it automatically; others send all water bills for the financial year to ConcessionsSA.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/water-and-sewerage-rate-concession', '2025-26 thresholds were $910.00 and $590.40. Top-up amount not stated.'),
('SA-009', 'Emergency Services Levy Remission', 'SA Government (RevenueSA / ConcessionsSA)', 'State', 'SA', 'Home and Rates', 'Money off the Emergency Services Levy on the home you own and live in.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Registered owner or life estate holder living at the property on 1 July, holding a Pensioner Concession Card, Commonwealth Seniors Health Card, Low Income Health Care Card, eligible Veteran Gold Card or eligible Centrelink payment.', 'Up to $46 a year off your ESL bill', 46, 'Current (year not stated on page)', 'Check your ESL notice or SA Water bill first (pensioners may already get it); otherwise apply with the household concessions form.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/emergency-services-levy-remission', 'Not available to residential park residents. Veteran Gold Card only if TPI, EDA, War Widow or 80+ impairment points (MRCA).'),
('SA-010', 'Residential Park Resident Concession', 'SA Government (ConcessionsSA)', 'State', 'SA', 'Bills', 'A combined energy, water and sewerage payment for people living in a caravan or residential park.', array['PCC','CSHC','HCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Live in a residential or caravan park as your main home and hold an eligible concession card or Centrelink payment.', 'Up to $823.51 a year (own dwelling, pay water, sewerage and energy) or up to $488.47 (tenants paying water and energy), paid quarterly', 823.51, 'Current figure on page (page updated 1 July 2026, indexed yearly; likely 2026-27)', 'Email the Application for Household Concessions form with documents to concessions@sa.gov.au.', '1800 307 758', 'https://www.sa.gov.au/topics/care-and-support/concessions/household-concessions/residential-park-resident-concessions', 'Page does not list eligible cards; assumed same as energy/COLC (CSHC may not count for the water part). Can also get Cost of Living Concession, not ESL remission.'),
('SA-011', 'Emergency Electricity Payment Scheme', 'SA Government', 'State', 'SA', 'Payments', 'One-off help to pay an electricity debt if you are at risk of being cut off.', array['NONE']::text[], null, array['electricity_account','hardship']::text[], array[]::text[], true, 'You have an electricity debt and have been, or are at risk of being, disconnected.', 'Amount not stated', null, 'Ongoing', 'Contact a financial counsellor (Financial Wellbeing Program partner), who assesses you and lodges the application.', '13 23 24', 'https://www.sa.gov.au/topics/care-and-support/concessions/financial-aid/emergency-financial-aid', 'Amount not on the page. Phone is Service SA general line, not EEPS-specific.'),
('SA-012', 'Seniors Card SA', 'SA Government (Office for Ageing Well)', 'State', 'SA', 'Discounts', 'Free card for South Australians aged 60+ giving free public transport and business discounts.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or over (or 50+ and Aboriginal or Torres Strait Islander), Australian citizen or permanent resident living in SA. No limit on work hours.', 'Free card; free Adelaide Metro travel and discounts at participating businesses', null, 'Ongoing', 'Apply online at seniorscard.sa.gov.au (need driver''s licence, Medicare or pension card number) or with a paper form from a public library.', '1800 819 961', 'https://www.seniorscard.sa.gov.au/membership/apply-for-a-seniors-card', 'Replacement card $15 (free for PCC holders). Interstate Seniors Card holders get a free 14-day off-peak Adelaide Metro pass. Discounts accepted by many interstate and NZ partners.'),
('SA-013', 'Free public transport for Seniors Card holders', 'Adelaide Metro (SA Government)', 'State', 'SA', 'Transport', 'Seniors Card holders travel free on Adelaide buses, trains and trams at any time.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Hold a South Australian Seniors Card (validate it when boarding).', 'Free travel at all times on Adelaide Metro', null, 'Ongoing', 'Use your Seniors Card as your ticket and validate it each time you board.', '1300 311 108', 'https://adelaidemetro.com.au/tickets-and-fares/seniors-card', 'Not free on regional private bus services, but concession fares apply there.'),
('SA-014', 'Public transport concession fares', 'Adelaide Metro (SA Government)', 'State', 'SA', 'Transport', 'Half-price fares on Adelaide buses, trains and trams for concession card holders.', array['PCC','HCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Hold an eligible government concession card such as a Pensioner Concession Card, Health Care Card or DVA Veteran Gold Card.', 'Concession metroCARD $2.25 peak / $1.30 off-peak; 28-day pass $59.60', null, 'Current fares (2026)', 'Buy a concession metroCARD and carry proof of eligibility.', '1300 311 108', 'https://www.sa.gov.au/topics/care-and-support/concessions/transport/transport-concessions', 'Fares from adelaidemetro.com.au fares page. CSHC not listed as eligible; check. Seniors Card holders travel free instead.'),
('SA-015', 'Pensioner registration and licence concession', 'Department for Infrastructure and Transport (Service SA)', 'State', 'SA', 'Transport', 'Half off car registration and your driver''s licence fee if you have a pension card.', array['PCC','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Hold an Australian Government pension card (Pensioner Concession Card). A Health Care Card or Commonwealth Seniors Health Card alone does not qualify.', '50% off the registration component for one vehicle and one trailer/caravan, 50% off licence fee, and no stamp duty on CTP insurance', null, 'Ongoing', 'Phone Service SA on 13 10 84 (consent to Centrelink check) or apply in person at a Service SA centre.', '13 10 84', 'https://www.sa.gov.au/topics/care-and-support/concessions/transport/registration-and-licence-concessions', 'DVA pension cards assumed to count as Australian Government pension cards; check. Value depends on vehicle.'),
('SA-016', 'Incapacitated ex-service person''s registration concession', 'Department for Infrastructure and Transport (Service SA)', 'State', 'SA', 'Transport', 'Two-thirds off rego and half off licence fee for totally incapacitated veterans.', array['DVA_GOLD']::text[], null, array['veteran','car_owner']::text[], array[]::text[], true, 'Former ADF member totally incapacitated by service-related injury, e.g. Gold Card endorsed TPI or EDA, or a qualifying DVA letter.', '66.6% off registration for one vehicle, 50% off licence fee, exempt from CTP stamp duty and vehicle stamp duty', null, 'Ongoing', 'Apply at Service SA with the form and DVA proof.', '13 10 84', 'https://www.sa.gov.au/topics/care-and-support/concessions/transport/registration-and-licence-concessions', 'Not for trailers, caravans or heavy vehicles.'),
('SA-017', 'Incapacitated person''s registration concession', 'Department for Infrastructure and Transport (Service SA)', 'State', 'SA', 'Transport', 'Half off rego for people who have lost the use of their legs and can''t use public transport.', array['NONE']::text[], null, array['mobility_need','car_owner']::text[], array[]::text[], true, 'Lost the use of one or both legs and cannot use public transport as a result.', '50% off registration for one vehicle, exempt from CTP stamp duty and vehicle stamp duty', null, 'Ongoing', 'Apply in person at Service SA with the form and a medical certificate.', '13 10 84', 'https://www.sa.gov.au/topics/care-and-support/concessions/transport/registration-and-licence-concessions', null),
('SA-018', 'SA Transport Subsidy Scheme (taxi fares)', 'Department for Infrastructure and Transport', 'State', 'SA', 'Transport', 'Half or more off taxi fares for people with a severe permanent disability.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Permanent and severe disability that limits your ability to use public transport.', '50% of fare up to $20 a trip; 75% up to $30 a trip if permanently wheelchair dependent', null, 'Current', 'Post the application (parts completed by GP, specialist or mobility instructor) with a certified photo to SATSS, GPO Box 2830, Adelaide SA 5001.', '1300 360 840', 'https://www.sa.gov.au/topics/driving-and-transport/disability/taxi-fare-subsidy-scheme', null),
('SA-019', 'Disability parking permit', 'Department for Infrastructure and Transport (Service SA)', 'State', 'SA', 'Transport', 'Permit to park in disability spaces if you have trouble walking.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Use a mobility aid or have a condition that severely limits walking, or a significant cognitive/neurological condition needing support to move safely. No age limit.', 'Lets you use disability parking; costs $15 temporary or $26 permanent (up to 5 years)', null, 'Current fees', 'Complete the form with your health practitioner and lodge with fee at Service SA or by post.', '13 10 84', 'https://sa.gov.au/topics/driving-and-transport/disability/disability-parking-permit/apply', 'Not a cash benefit; there is a fee.'),
('SA-020', 'Companion Card', 'SA Department of Human Services', 'State', 'SA', 'Discounts', 'Your carer or companion gets in free at participating venues and on transport.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Significant and permanent disability needing a companion''s support to take part in community activities.', 'Free entry or ticket for your companion at participating venues', null, 'Ongoing', 'Apply via the sa.gov.au Companion Card page.', '1800 667 110', 'https://dhs.sa.gov.au/how-we-help/cost-of-living/concessions/companion-card', 'Full eligibility criteria not on page opened; ''requires'' tag is an approximation.'),
('SA-021', 'Patient Assistance Transport Scheme (PATS)', 'SA Government (SA Health)', 'State', 'SA', 'Health', 'Help with fuel and accommodation if you travel over 100 km to see a specialist.', array['NONE']::text[], null, array['rural']::text[], array[]::text[], true, 'Travel more than 100 km each way to the nearest approved specialist service (from 1 July 2026, renal or oncology patients attending 3 times a week and travelling 50-100 km may qualify).', '34.4 cents per km for your car; accommodation $110 a night (patient) or $154 (patient and escort)', null, 'From 1 July 2026', 'Claim online through the PATS portal or at a regional PATS office.', '1300 341 684', 'https://www.pats.sa.gov.au/', 'About page (pats.sa.gov.au/about-2/) still shows older rates (33.6c/km, $44/night); homepage 30 June 2026 update used. Concession card holders can ask for an advance payment.'),
('SA-022', 'SA Dental Service (adult public dental)', 'SA Dental (SA Health)', 'State', 'SA', 'Health', 'Low-cost public dental care including check-ups, fillings and dentures for concession card holders.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'Adults living in SA with a current Health Care Card or Pensioner Concession Card. DVA cards and the Commonwealth Seniors Health Card are not accepted.', 'Reduced-fee general and denture care; you pay a co-payment', null, 'Fees rise each 1 July', 'Phone your closest SA Dental clinic to book or join the waiting list.', '1800 022 222', 'https://www.dental.sa.gov.au/adults/who-can-attend', 'Co-payment amounts not found on pages opened. Waiting lists apply. Phone given is healthdirect after hours; use Find a Clinic for clinic numbers.'),
('SA-023', 'GlassesSA (spectacles scheme)', 'SA Government', 'State', 'SA', 'Health', 'Low-cost glasses every three years for pension and health care card holders.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'Live in SA and hold a Pensioner Concession Card, Health Care Card or Low Income Health Care Card. Not for DVA Gold Card holders or people eligible for DVA optical services.', 'One pair every 3 years; you pay at most $25 single vision, $50 bifocal, $100 multifocal. Free contact lenses for certain eye conditions', null, 'Current', 'Show your card to a GlassesSA-authorised optometrist and choose from basic frames.', '1300 762 577', 'https://www.sa.gov.au/topics/care-and-support/concessions/health-concessions/glassessa', null),
('SA-024', 'Personal Alert AssistanceSA rebate', 'SA Government', 'State', 'SA', 'Health', 'Help paying for a personal alarm and monitoring for older pensioners at risk.', array['PCC']::text[], null, array['aged_70']::text[], array[]::text[], true, 'Aged 75+ (65+ if Aboriginal), Pensioner Concession Card, SA permanent resident, meet clinical/functional/social criteria and have had a My Aged Care assessment with an eligible outcome.', 'Rebate towards an approved alarm system and monitoring (amount not stated)', null, 'Current', 'Get a My Aged Care assessment, have a health professional sign the form, email it to paasa@sa.gov.au.', '1300 700 169', 'https://www.sa.gov.au/topics/care-and-support/concessions/health-concessions/personal-alert-systems', 'Age is 75+; aged_70 tag is the closest available. Not for DVA Gold Card holders or Home Care Package levels 2-4.'),
('SA-025', 'SA Ambulance Cover pensioner discount', 'SA Ambulance Service', 'State', 'SA', 'Health', 'Ambulance cover is not free for pensioners in SA, but pension card holders pay a reduced price.', array['PCC']::text[], null, array[]::text[], array[]::text[], true, 'Eligible pensioner concession card holders.', 'Pensioner single cover $63.50 a year (family $126) vs standard $106 single', null, '2026', 'Join through SA Ambulance Service.', '1300 136 272', 'https://saambulance.sa.gov.au/membership/ambulance-cover/', 'Emergency call-out without cover is $1,247 plus $7.15/km (fees page). SA Pension Concession Card holders ''may be eligible for concession of the gazetted fees''. Saving vs standard is $42.50 a year single.'),
('SA-026', 'Seniors Rate Postponement Scheme', 'Local councils (Local Government Act 1999)', 'Council', 'SA', 'Home and Rates', 'Seniors Card holders can delay paying part of their council rates until the home is sold.', array['SENIORS_CARD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'State Seniors Card holder, rates on your principal place of residence.', 'Postpone a portion of council rates (amounts and interest set by law/council)', null, 'Ongoing', 'Apply to your local council''s rates officer.', null, 'https://www.dhud.sa.gov.au/our-department/local-govt/office-of-local-government/council-rates', 'Postponed amount is a debt on the property. Minimum payable and interest not on source. Councils may also give rate remissions to concession or Seniors Card holders, and remit/postpone for hardship (s182).'),
('SA-027', 'Seniors Downsizing Stamp Duty Relief', 'RevenueSA', 'State', 'SA', 'Home and Rates', 'No stamp duty on a new, smaller home if you are 60+ and selling your current home.', array['NONE']::text[], null, array['aged_60','homeowner']::text[], array[]::text[], true, 'At least one buyer aged 60+, selling your SA principal residence within 12 months, buying a new home, off-the-plan apartment or vacant land with smaller land size, and living there 6 months. Contracts from 25 March 2026.', 'Full stamp duty relief up to $2 million (new home/apartment) or $1.2 million (vacant land); partial relief just above', null, 'Contracts on or after 25 March 2026', 'Your conveyancer usually lodges it, or apply directly to RevenueSA.', '08 8372 7534', 'https://revenuesa.sa.gov.au/seniors-downsizing-stamp-duty-relief', 'One-off; value depends on property price.'),
('SA-028', 'Private Rental Assistance', 'SA Housing Trust', 'State', 'SA', 'Home and Rates', 'Help with bond and rent in advance for low-income renters moving into private rental.', array['NONE']::text[], null, array['renter','low_income']::text[], array[]::text[], true, 'Meet income and asset limits, rent no more than 50% of income, no residential property, SA property.', 'Bond guarantee and rent-in-advance/arrears grants (amounts not stated)', null, 'Current', 'Landlord/agent completes declaration; email the reference number to housingcustomers@sa.gov.au, or apply at an SA Housing Trust office.', '131 299', 'https://housing.sa.gov.au/housing-supports/private-rental-assistance', null),
('SA-029', 'Funeral AssistanceSA', 'SA Government', 'State', 'SA', 'Payments', 'Basic funeral or up to $625 grant when a low-income person dies and the family can''t pay.', array['NONE']::text[], null, array['low_income','hardship']::text[], array[]::text[], true, 'Deceased was an SA resident on a pension/benefit or low income with estate under $4,000, and immediate relatives also can''t pay.', 'Basic contract funeral, or an after-the-event grant up to $625 paid to the funeral director', null, 'Current', 'Notify Centrelink of the death, then complete the online Funeral AssistanceSA application.', '1300 762 577', 'https://www.sa.gov.au/topics/care-and-support/concessions/funeral-assistance-program', 'One-off.'),
('TAS-001', 'Annual Electricity Concession', 'Tas Government (via electricity retailer)', 'State', 'TAS', 'Bills', 'A daily discount on your electricity bill, worth about $673 a year.', array['PCC','HCC']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Pensioner Concession Card (Centrelink or DVA), Health Care Card, ImmiCard (Bridging Visa E) or Tasmanian Concession Card; name on card must match the account holder; principal place of residence on a general domestic tariff.', '$1.84347 a day (about $673 a year)', 673, '2026-27 (from 1 July 2026)', 'Contact your electricity retailer or send them the Annual Electricity Concession application form.', null, 'https://www.sro.tas.gov.au/electricity-concessions/annual-electricity-concession', 'Commonwealth Seniors Health Card not listed. Concessions.tas.gov.au master list still shows the older 176.866 cents/day rate.'),
('TAS-002', 'Annual Electricity Concession (embedded networks)', 'Tas Government', 'State', 'TAS', 'Bills', 'If your power comes through a caravan park, retirement village or similar embedded network, you can get the electricity concession as a yearly payment.', array['PCC','HCC']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Same eligibility as the Annual Electricity Concession but you are supplied through an embedded network.', '$673 one-off payment for 2026-27', 673, '2026-27', 'Apply through a Service Tasmania outlet or the Service Tasmania website.', '1300 135 513', 'https://www.sro.tas.gov.au/electricity-concessions/annual-electricity-concession', 'Embedded network rates for medical cooling/heating and life support are also paid annually.'),
('TAS-003', 'Medical Cooling or Heating Concession', 'Tas Government (via electricity retailer)', 'State', 'TAS', 'Bills', 'A daily discount on your power bill if you or someone you live with has a medical condition made worse by heat or cold.', array['PCC','HCC']::text[], null, array['electricity_account','medical_condition']::text[], array[]::text[], true, 'Eligible for the Annual Electricity Concession; hold a PCC or HCC; you or a household member has a qualifying condition (e.g. MS, Parkinson''s, lupus) certified by a GP or specialist; recertify every four years.', '55.216 cents a day ($201.54 a year)', 201.54, '2026-27 (from 1 July 2026)', 'Get the form from your retailer, Service Tasmania or SRO, have your doctor certify it, and send it to your retailer.', null, 'https://www.sro.tas.gov.au/electricity-concessions/medical-cooling-or-heating-concession', null),
('TAS-004', 'Life Support Concession', 'Tas Government (via electricity retailer)', 'State', 'TAS', 'Bills', 'A daily discount on your power bill if you or someone you live with uses an approved life support machine at home.', array['NONE']::text[], null, array['electricity_account','life_support']::text[], array[]::text[], true, 'Account holder requires, or lives with someone who requires, an approved life support system at the principal place of residence. No concession card needed.', 'From $50.01 a year (mains nebuliser) to $939.82 a year (phototherapy machine); oxygen concentrator $498.72 a year', null, '2026-27 (from 1 July 2026)', 'Have your doctor certify the life support application form and send it to your electricity retailer.', null, 'https://www.sro.tas.gov.au/electricity-concessions/life-support-concession', 'Value depends on the device; highest single-device rate is $939.82 a year.'),
('TAS-005', 'Heating Allowance', 'Department of Premier and Cabinet', 'State', 'TAS', 'Bills', 'A small yearly payment to help pensioners with low savings pay for heating.', array['PCC']::text[], null, array['age_pension','low_income']::text[], array[]::text[], true, 'Means-tested pensioners holding an eligible concession card; cash assets under $1,750 (single) or $2,750 (couple); other conditions apply.', '$56 a year, paid as two $28 payments', 56, 'Current (year not stated)', 'Apply online or request a form by phone or email (heatingallowance@dpac.tas.gov.au).', '1800 300 068', 'https://www.concessions.tas.gov.au/concessions/electricity_and_heating/heating', 'Page does not name exactly which cards qualify; master list shows HCC and PCC.'),
('TAS-006', 'Energy Hardship Fund', 'Tas Government (run by The Salvation Army)', 'State', 'TAS', 'Bills', 'Help for Tasmanians struggling to pay their energy bills.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Tasmanians in energy bill hardship; detailed criteria not stated in the budget release.', 'Amount not stated', null, '2026-27 Budget', 'Contact The Salvation Army.', null, 'https://www.premier.tas.gov.au/budget-2026/budget-releases/delivering-the-energy-support-and-security-tasmania-deserves', 'Budget release only ($450,000 funding); no individual amount or application page found.'),
('TAS-007', 'Council Rates Remission for Pensioners', 'Tas Government (via local council)', 'State', 'TAS', 'Home and Rates', 'Money off council rates on the home you live in.', array['PCC','HCC','DVA_GOLD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'PCC, HCC, or DVA Gold Card (TPI or War Widow/Widower) issued on or before 1 July 2026; principal place of residence. CSHC alone does not qualify.', 'Lesser of 30% of your rates or $591 ($401 if you are a TasWater customer)', 591, '2026-27', 'Apply in person at your council by 31 March 2027, showing your card. Back-claims for one prior year allowed.', null, 'https://www.sro.tas.gov.au/pensioner-rates-remission', '$401 cap applies to TasWater clients because they also get the TasWater concession.'),
('TAS-008', 'Water and Sewerage Concession', 'Tas Government (via TasWater)', 'State', 'TAS', 'Bills', 'Money off the TasWater access charges for water and sewerage.', array['PCC','HCC','DVA_GOLD']::text[], null, array['water_account','homeowner']::text[], array[]::text[], true, 'Eligible HCC, PCC or DVA Gold Card holders who are TasWater customers.', 'Up to $242.56 a year ($121.28 water, $121.28 sewerage)', 242.56, '2025-26', 'Contact TasWater.', '136 992', 'https://www.concessions.tas.gov.au/concessions', 'Covers access charges only, not usage. 2026-27 amount not confirmed; TasWater site failed to load.'),
('TAS-009', 'Tasmanian Seniors Card', 'Tas Government', 'State', 'TAS', 'Discounts', 'A free card giving discounts at businesses and on some government fees for Tasmanians aged 60+.', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'Aged 60 or over, live in Tasmania and work less than 20 hours a week.', 'Discounts vary by business', null, 'Current', 'Apply online or at any Service Tasmania centre.', '1300 135 513', 'https://www.concessions.tas.gov.au/more_information/concessions_cards/tasmanian_seniors_card', 'Page does not state a fee.'),
('TAS-010', 'Adult Bus and Ferry Concession Fares', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Half-price fares on Metro and other buses and the River Derwent ferry.', array['PCC','HCC','SENIORS_CARD','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'An eligible concession card, or aged 70 and over, or DVA Gold Card printed War Widow, among others.', '50% off the full fare, plus a further 20% off with a smartcard (e.g. Greencard) or 10-trip ticket', null, 'Current', 'Show your eligible card when buying a ticket or registering a smartcard.', null, 'https://www.concessions.tas.gov.au/concessions/transport/metromerseylink_buses2', 'Aged 70+ qualifies without a card. Master list shows Seniors Card as eligible; transport page wording is ''eligible concession card''.'),
('TAS-011', 'Free Bus Travel for DVA TPI and EDA Pensioners', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Free bus and ferry travel for veterans on the TPI or EDA pension.', array['DVA_GOLD']::text[], null, array['veteran']::text[], array[]::text[], true, 'DVA Veteran Gold Card printed TPI or EDA.', 'Free travel', null, 'Current', 'Get a Greencard to use on Metro buses.', null, 'https://www.concessions.tas.gov.au/concessions/transport/metromerseylink_buses2', null),
('TAS-012', 'Vision Impaired Travel Pass', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Free bus and ferry travel for people who are legally blind, plus an attendant and guide dog.', array['PCC']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'PCC with blind pension endorsement or ophthalmologist assessment.', 'Free travel for cardholder, attendant and guide dog', null, 'Current', 'Apply via Department of State Growth (transport.tas.gov.au).', null, 'https://www.concessions.tas.gov.au/concessions', null),
('TAS-013', 'Taxi Subsidy Program', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Half-price (or 60% off) taxi trips for people with a severe disability who cannot use buses.', array['PCC','HCC','CSHC']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'Transport Access Scheme member; 60% rate is for wheelchair-reliant members.', '50% off, up to $25 a trip; or 60% off, up to $30 a trip (wheelchair reliant)', null, 'Current', 'Apply to join the Transport Access Scheme via transport.tas.gov.au.', null, 'https://www.concessions.tas.gov.au/concessions', 'Master list shows concession cards and a generic option; membership of the Transport Access Scheme is the key requirement.'),
('TAS-014', 'Bass Strait Islands Age Pension Air Travel Subsidy', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Age pensioners on King or Flinders Island get half of one return mainland flight back each year.', array['PCC']::text[], null, array['age_pension','rural']::text[], array[]::text[], true, 'Age pensioner (PCC) living on a Bass Strait island.', '50% rebate on one return trip to mainland Tasmania per financial year', null, 'Current', 'Apply via transport.tas.gov.au.', null, 'https://www.concessions.tas.gov.au/concessions', null),
('TAS-015', 'SeaLink Bruny Island Ferry Concession', 'SeaLink Bruny Island', 'Private', 'TAS', 'Transport', 'Cheaper vehicle fares on the Bruny Island ferry.', array['PCC','CSHC']::text[], null, array['car_owner']::text[], array[]::text[], true, 'CSHC or PCC holder driving; show card at check-in.', 'Discounted driver fare (amount not stated)', null, 'Current', 'Show your card at check-in.', '1300 127 869', 'https://www.concessions.tas.gov.au/concessions', null),
('TAS-016', 'Spirit of Tasmania Pensioner Fares', 'TT-Line', 'Private', 'TAS', 'Transport', 'Discounted passenger fares on the Spirit of Tasmania.', array['PCC']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card holders; subject to availability.', 'Discounted selected passenger fares (amount not stated)', null, 'Current', 'Book with Spirit of Tasmania and quote your card.', '132 010', 'https://www.concessions.tas.gov.au/concessions', null),
('TAS-017', 'Motor Tax 40% Rebate', 'Department of State Growth', 'State', 'TAS', 'Transport', '40% off the motor tax part of registration for one car.', array['PCC','HCC','DVA_WHITE','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'Eligible concession card holder; one non-business vehicle up to 4.5 tonnes.', '40% rebate on motor tax', null, 'Current', 'Contact the Vehicle Registration Unit or Service Tasmania.', '1300 135 513', 'https://www.concessions.tas.gov.au/concessions', null),
('TAS-018', 'Vehicle Registration Concession', 'Department of State Growth', 'State', 'TAS', 'Transport', 'Discount on 12-month registration fees for one vehicle.', array['PCC','HCC','DVA_WHITE','DVA_GOLD']::text[], null, array['car_owner']::text[], array[]::text[], true, 'HCC, PCC, DVA White or Gold Card, or Transport Access Scheme member; one vehicle.', 'Car $60.20 off; motorcycle $55.07 off a 12-month registration', 60.2, 'Current (year not stated)', 'Contact the Vehicle Registration Unit or Service Tasmania.', '1300 135 513', 'https://www.concessions.tas.gov.au/concessions', 'May overlap with the motor tax rebate; check whether the two are additive.'),
