('VIC-027', 'Victorian Seniors Card', 'Vic Government (Seniors Card)', 'State', 'VIC', 'Discounts', 'Free card; discounts at thousands of businesses (most 10%+).', array['NONE']::text[], null, array['aged_60']::text[], array['SENIORS_CARD']::text[], true, 'None; Victorian resident aged 60+, working under 35 hours a week', 'Free card; discounts at thousands of businesses (most 10%+)', null, 'Ongoing', 'Apply online with Medicare card', '1300 797 210', 'https://www.seniorsonline.vic.gov.au/seniors-card/seniors-card-FAQS', 'Full-time workers get the Seniors Business Discount Card instead'),
