('VIC-032', 'Recreational fishing licence exemption', 'Victorian Fisheries Authority', 'State', 'VIC', 'Discounts', 'No licence fee.', array['DVA_GOLD','PCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Victorian Seniors Card, or PCC marked AGE/DSP/CAR, or DVA Gold TPI; Or aged over 70', 'No licence fee', null, 'Ongoing', 'Carry your card when fishing', null, 'https://services.dffh.vic.gov.au/sites/default/files/2025-09/Victorian%20concessions%20-%20guide%20to%20discounts%20and%20services-september-2025.pdf', 'Licence fee not stated in guide'),
