('VIC-034', 'Pet registration concession', 'Local council', 'Council', 'VIC', 'Discounts', 'Reduced cat and dog registration; varies by council.', array['HCC','PCC']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card (some councils also HCC)', 'Reduced cat and dog registration; varies by council', null, 'Yearly', 'Ask your council', null, 'https://services.dffh.vic.gov.au/sites/default/files/2025-09/Victorian%20concessions%20-%20guide%20to%20discounts%20and%20services-september-2025.pdf', 'Varies by council'),
('VIC-035', 'Pensioner stamp duty exemption or concession', 'State Revenue Office Victoria', 'State', 'VIC', 'Home and Rates', 'Full or partial stamp duty exemption.', array['CSHC','HCC','PCC']::text[], null, array[]::text[], array[]::text[], true, 'Eligible Commonwealth concession cards; Buying a home to live in, under a value cap; once in a lifetime', 'Full or partial stamp duty exemption', null, 'Contracts from 1 July 2023', 'Apply through SRO at settlement', '13 21 61', 'https://www.sro.vic.gov.au/buying-property/land-transfer-stamp-duty/concessions-exemptions-and-waivers/pensioner-and-concession-cardholder-duty-reduction/pensioner-and-concession-cardholder-duty-reduction-contracts-1-july-2023', 'SRO page did not load; thresholds still to fill'),
('VIC-036', 'Wills and power of attorney discount', 'State Trustees', 'Private', 'VIC', 'Discounts', '20% off preparing or updating a will or power of attorney.', array['CSHC','HCC','PCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Victorian Seniors Card or concession card; Appointment in Melbourne CBD or Dandenong', '20% off preparing or updating a will or power of attorney', null, 'Ongoing', 'Book an appointment', null, 'https://www.seniorsonline.vic.gov.au/discounts/state-trustees-limited-0', 'Private-sector offer via Seniors Card directory'),
('VIC-037', 'No Interest Loan Scheme', 'Good Shepherd (NILS)', 'Private', 'VIC', 'Payments', 'Interest-free loan up to $1,500 (essentials) or $5,000 (vehicle).', array['HCC','PCC']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card or Health Care Card, or low income; Able to repay', 'Interest-free loan up to $1,500 (essentials) or $5,000 (vehicle)', null, 'Ongoing', 'Apply online or by phone', '13 64 57', 'https://services.dffh.vic.gov.au/sites/default/files/2025-09/Victorian%20concessions%20-%20guide%20to%20discounts%20and%20services-september-2025.pdf', 'Not-for-profit, national scheme listed in Vic guide'),
('WA-001', 'Energy Assistance Payment', 'WA Government (via Synergy or Horizon Power)', 'State', 'WA', 'Bills', 'A yearly credit on your electricity bill, paid in daily amounts, if you hold a concession card.', array['PCC','HCC','DVA_GOLD','CSHC']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Residential electricity account holder with a Pensioner Concession Card (Centrelink or DVA), Health Care Card or DVA Gold Card. Horizon Power and the ECES also list the Commonwealth Seniors Health Card.', '$377.14 a year credited to your electricity account', 377.14, 'From 1 July 2026', 'Add your concession card in your Synergy or Horizon Power online account, or phone your retailer.', 'Horizon Power 1800 267 926; Synergy 13 13 53', 'https://www.horizonpower.com.au/for-home/managing-your-account/concessions-and-rebates/', 'Synergy''s page still shows $334.49 (older year) and does not list CSHC; Horizon Power and RevenueWA ECES pages show $377.14 from 1 July 2026 and include CSHC. Check CSHC eligibility with Synergy. Replaced the old Cost of Living Assistance payment.'),
('WA-002', 'Air Conditioning Rebate', 'WA Government (via Synergy or Horizon Power)', 'State', 'WA', 'Bills', 'Help with air-conditioner running costs for seniors living in the hot north of WA.', array['SENIORS_CARD','PCC','CSHC']::text[], '[["SENIORS_CARD","PCC"],["SENIORS_CARD","CSHC"]]'::jsonb, array['electricity_account','rural']::text[], array[]::text[], true, 'Live north of the 26th parallel and/or the 50 Day Relative Strain Index line, and hold a WA Seniors Card plus a Commonwealth Seniors Health Card, Pensioner Concession Card or DVA Pensioner Concession Card (both cards needed). Families with dependent children on a concession card also qualify. Air conditioner must be installed at the home.', '$78.98 for each eligible month (cost of 221.8 kWh); 2 to 10 eligible months depending on town', null, 'From 1 July 2026', 'Apply online through Synergy or Horizon Power with your bill and card details.', 'Horizon Power 1800 267 926', 'https://www.wa.gov.au/service/community-services/grants-and-subsidies/apply-energy-concession', 'Needs BOTH a WA Seniors Card and one of PCC/CSHC/DVA PCC for seniors. Max per year = $78.98 x eligible months for your town (up to about $790). Synergy page shows older $70.05/month example.'),
('WA-003', 'Account Establishment Fee Rebate', 'WA Government (via Synergy or Horizon Power)', 'State', 'WA', 'Bills', 'One-off refund of the fee to open a new electricity account.', array['PCC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Residential customer opening a new electricity account with a Health Care Card, Pensioner Concession Card, DVA Gold Card or DVA Pensioner Concession Card.', 'One-off $27.28 (Horizon Power) / $26.84 (Synergy) on your first bill', null, '2026-27 (Horizon); Synergy figure may be older year', 'Tell your retailer you hold a concession card when you open the account.', 'Horizon Power 1800 267 926', 'https://www.horizonpower.com.au/for-home/managing-your-account/concessions-and-rebates/', 'One-off, so max_annual_value null.'),
('WA-004', 'Reduced Meter Test Fee', 'WA Government (Energy Policy WA)', 'State', 'WA', 'Bills', 'A cheaper fee if you ask for your electricity meter to be tested, refunded if the meter is faulty.', array['PCC','HCC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'Holders of a Centrelink Health Care Card, Pensioner Concession Card, DVA Gold Card or DVA Pensioner Concession Card.', 'Reduced meter test fee (amount not stated); fee refunded if meter is faulty', null, 'Ongoing', 'Ask your electricity retailer for a meter test and give your concession card details.', null, 'https://www.wa.gov.au/organisation/energy-policy-wa/household-energy-pricing-and-payment-support', 'Fee amount not shown on source.'),
('WA-005', 'Energy Concession Extension Scheme (ECES)', 'RevenueWA (Department of Finance)', 'State', 'WA', 'Bills', 'Gets you the Energy Assistance Payment if you pay for power through a caravan park, retirement village or other landlord/on-seller instead of Synergy or Horizon Power.', array['PCC','HCC','CSHC','DVA_GOLD']::text[], null, array['electricity_account']::text[], array[]::text[], true, 'You pay for electricity through an eligible on-selling arrangement (e.g. retirement village, caravan park, other retailer such as Perth Energy or Alinta) and you or a household member hold a PCC, HCC, CSHC or DVA Gold Card. WA Seniors Card alone does not qualify. Tenants must have lived there or have a lease of at least 3 months.', 'Energy Assistance Payment $377.14 a year paid by EFT (plus Air Conditioning Rebate if eligible)', 377.14, 'From 1 July 2026', 'Apply online via RevenueWAConnect Online Services Portal; renew yearly by your anniversary date.', '08 9262 1486 (country landlines 1300 368 364)', 'https://www.wa.gov.au/service/community-services/grants-and-subsidies/apply-energy-concession', null),
('WA-006', 'Life Support Equipment Energy Subsidy', 'RevenueWA (Department of Finance)', 'State', 'WA', 'Health', 'A yearly payment to help with the power costs of running life support equipment at home.', array['PCC','HCC']::text[], null, array['life_support']::text[], array[]::text[], true, 'Patient (or their guardian/carer) depends on specified life support equipment at home on specialist advice, and holds a Pensioner Concession Card (Centrelink or DVA), Health Care Card (not CSHC) or Health Care Interim Voucher.', 'From $58 (nebuliser) to $1,517 (child oxygen concentrator) a year depending on equipment; e.g. CPAP $530, adult oxygen concentrator $1,011', 1517, '2026 (page updated Oct 2026)', 'Apply online through RevenueWAConnect; your doctor completes the medical authorisation. Renew yearly.', '08 9262 1373 (country landlines 1300 368 364)', 'https://www.wa.gov.au/government/publications/subsidies-life-support-fs', 'Max shown is the highest item rate (child oxygen concentrator); most adults get less. CSHC is excluded.'),
('WA-007', 'Thermoregulatory Dysfunction Energy Subsidy', 'RevenueWA (Department of Finance)', 'State', 'WA', 'Health', 'A yearly payment for people whose medical condition means they must heat or cool their home.', array['PCC','HCC']::text[], null, array['medical_condition']::text[], array[]::text[], true, 'Patient (or guardian/carer in the same household) holds a Pensioner Concession Card, Health Care Card (not CSHC) or Health Care Interim Voucher; patient meets at least two of three qualifying conditions, certified by a doctor who has treated them for 3+ months.', '$832 a year paid in advance (up to two payments per household)', 832, '2026', 'Apply online through RevenueWAConnect; your doctor completes the medical form. Renew yearly.', '08 9262 1373 (country landlines 1300 368 364)', 'https://www.wa.gov.au/government/publications/subsidies-thermoregulatory-dysfunction-fs', null),
('WA-008', 'Hardship Utility Grant Scheme (HUGS)', 'Department of Communities (via your utility provider)', 'State', 'WA', 'Bills', 'A grant to help pay an overdue electricity, gas or water bill if you are in financial hardship.', array['NONE']::text[], null, array['hardship']::text[], array[]::text[], true, 'Assessed by your utility provider as being in financial hardship, completed a payment arrangement of at least 90 days, and still owe more than $300. Must live at the supply address. Water customers must be owner-occupiers. Not for bottled gas.', 'Up to $640 a year (south of the 26th parallel) or $1,060 (Denham and north), max 85% of the balance', 1060, 'Per financial year', 'Call your utility provider, join their hardship program, then ask them to start a HUGS application after 90 days.', 'Synergy 13 13 53; Water Corporation 13 13 85; Horizon Power 1800 267 926', 'https://www.wa.gov.au/service/community-services/grants-and-subsidies/hardship-utility-grant-scheme', 'Max $1,060 applies only in the north; $640 south.'),
('WA-009', 'Local Government Rates Rebate (pensioners, and Seniors Card plus CSHC)', 'Water Corporation / RevenueWA (applied by your council)', 'State', 'WA', 'Home and Rates', 'Up to half off your council rates if you own and live in your home.', array['PCC','DVA_GOLD','SENIORS_CARD','CSHC']::text[], '[["PCC"],["DVA_GOLD"],["SENIORS_CARD","CSHC"]]'::jsonb, array['homeowner']::text[], array[]::text[], true, 'Own and live in the property as your main home and hold a Pensioner Concession Card or State Concession Card, OR hold BOTH a WA Seniors Card and a Commonwealth Seniors Health Card. Includes long-term (5+ year) leases in retirement villages, lifestyle villages, park homes and caravan parks. DVA Gold Card holders may qualify via the State Concession Card.', 'Up to 50% off council rates, capped at $750 a year', 750, 'Rating year 1 July to 30 June (fact sheet as at July 2026)', 'Register once via Water Corporation''s online concession form; it tells your council. Pay the balance by 30 June to keep the rebate.', 'Water Corporation 1300 659 951; RevenueWA 08 9262 1373', 'https://www.wa.gov.au/system/files/2026-09/pensioners-seniors-concessions.pdf', 'Seniors Card + CSHC need BOTH cards; DVA_GOLD only through a State Concession Card (selected TPI/EDA/war widow categories).'),
('WA-010', 'Local Government Rates Rebate (WA Seniors Card only)', 'Water Corporation / RevenueWA (applied by your council)', 'State', 'WA', 'Home and Rates', 'A smaller discount on council rates for WA Seniors Card holders who own and live in their home.', array['SENIORS_CARD']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Own and live in the property as your main home and hold a WA Seniors Card (without a CSHC or PCC).', 'Up to 25% off council rates, capped at $100 a year', 100, 'Rating year 1 July to 30 June (fact sheet as at July 2026)', 'Register via Water Corporation''s online concession form; pay the balance by 30 June.', 'Water Corporation 1300 659 951', 'https://www.wa.gov.au/system/files/2026-09/pensioners-seniors-concessions.pdf', 'No deferral option for Seniors Card only.'),
('WA-011', 'Rates and water charges deferral', 'RevenueWA (Department of Finance)', 'State', 'WA', 'Home and Rates', 'Pensioners can put off paying council rates, ESL and water charges, interest-free, until the home is sold.', array['PCC','DVA_GOLD','SENIORS_CARD','CSHC']::text[], '[["PCC"],["DVA_GOLD"],["SENIORS_CARD","CSHC"]]'::jsonb, array['homeowner']::text[], array[]::text[], true, 'Registered for the pensioner rebate with a PCC or State Concession Card, or with BOTH a WA Seniors Card and CSHC. Seniors Card alone cannot defer.', 'Defer unpaid rates, ESL and water charges with no interest; repaid when you sell, move or on death (unless a surviving partner stays)', null, 'Ongoing', 'Charges are deferred automatically if unpaid by 30 June once you are registered.', 'RevenueWA 08 9262 1373', 'https://www.wa.gov.au/system/files/2026-09/pensioners-seniors-concessions.pdf', 'Cannot claim the rebate on amounts that are deferred.'),
('WA-012', 'Emergency Services Levy Rebate', 'RevenueWA (applied by your council)', 'State', 'WA', 'Home and Rates', 'The same pensioner or seniors discount you get on council rates also applies to the Emergency Services Levy.', array['PCC','DVA_GOLD','SENIORS_CARD','CSHC']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Registered for the council rates rebate: PCC or State Concession Card, or WA Seniors Card plus CSHC (up to 50%); WA Seniors Card only (up to 25%).', 'Up to 50% off the ESL (pensioners, Seniors + CSHC) or up to 25% (Seniors Card only)', null, 'Rating year 1 July to 30 June', 'Applied automatically once registered for the rates rebate.', 'RevenueWA 08 9262 1373', 'https://www.wa.gov.au/system/files/2026-09/pensioners-seniors-concessions.pdf', 'No dollar cap stated for ESL.'),
('WA-013', 'Underground Electricity Connection Charge Rebate', 'RevenueWA (applied by your council)', 'State', 'WA', 'Home and Rates', 'A discount on the council charge for connecting your home to underground power.', array['PCC','DVA_GOLD','SENIORS_CARD','CSHC']::text[], null, array['homeowner']::text[], array[]::text[], true, 'Owner-occupier registered for the pensioners and seniors rebate.', 'Up to 50% off (PCC, State Concession Card, or Seniors Card + CSHC); Seniors Card only up to 25%, capped at $100, first year only', null, 'As at July 2026', 'Applied once registered for the rates rebate; ask your council.', 'RevenueWA 08 9262 1373', 'https://www.wa.gov.au/system/files/2026-09/pensioners-seniors-concessions.pdf', 'One-off charge so no annual value.'),
('WA-014', 'Water Corporation service charge rebate (pensioners, and Seniors Card plus CSHC)', 'Water Corporation', 'State', 'WA', 'Bills', 'Up to half off the fixed water, sewerage and drainage charges on your Water Corporation bill.', array['PCC','DVA_GOLD','SENIORS_CARD','CSHC']::text[], '[["PCC"],["DVA_GOLD"],["SENIORS_CARD","CSHC"]]'::jsonb, array['water_account','homeowner']::text[], array[]::text[], true, 'Main residence; Pensioner Concession Card or State Concession Card, OR both a WA Seniors Card and CSHC (CSHC alone not eligible).', 'Up to 50% off service charges, capped at $600 a year (water $108.86, sewerage $436.15, drainage $54.99)', 600, '2026-27', 'Apply online with Water Corporation''s concession form; reapply if you move or get a new card.', '1300 659 951', 'https://www.watercorporation.com.au/Bill-and-account/Apply-for-a-concession', 'Interest is not charged on overdue bills for these cardholders.'),
('WA-015', 'Water Corporation water use rebate (pensioners)', 'Water Corporation', 'State', 'WA', 'Bills', 'Half off the cost of the first block of water you use each year, for pensioners including renters.', array['PCC','DVA_GOLD']::text[], null, array['water_account']::text[], array[]::text[], true, 'Pensioner Concession Card or State Concession Card holders. Tenants qualify if they do not live with the owner. Seniors Card + CSHC holders do not get this part.', '50% off the first 150 kL in Perth (max $158.10), first 400 kL south country, first 600 kL north country (max depends on town, e.g. $891.28)', 158.1, '2026-27 (metro figure)', 'Apply online with Water Corporation''s concession form.', '1300 659 951', 'https://www.watercorporation.com.au/Bill-and-account/Apply-for-a-concession', 'Country maximums are higher and vary by town class; $158.10 is the metro cap.'),
('WA-016', 'Water Corporation service charge rebate (WA Seniors Card only)', 'Water Corporation', 'State', 'WA', 'Bills', 'Up to $100 off fixed water charges for WA Seniors Card holders.', array['SENIORS_CARD']::text[], null, array['water_account','homeowner']::text[], array[]::text[], true, 'WA Seniors Card holder (without a PCC or CSHC), main residence.', 'Up to $100 a year off service charges', 100, '2026-27', 'Apply online with Water Corporation''s concession form.', '1300 659 951', 'https://www.watercorporation.com.au/Bill-and-account/Apply-for-a-concession', null),
('WA-017', 'Busselton Water pensioner and seniors rebate', 'Busselton Water', 'State', 'WA', 'Bills', 'Discount on Busselton Water bills for pensioners and seniors who own their home.', array['PCC','CSHC','DVA_GOLD','SENIORS_CARD']::text[], null, array['water_account','homeowner']::text[], array[]::text[], true, 'Own and live in the property (incl. long-term retirement village / park home leases). PCC, CSHC or State Concession Card: up to 50%; WA Seniors Card: up to 25% off supply charge only.', 'Up to 50% off supply charge and first 350 kL of water (PCC, CSHC, State Concession Card); up to 25% off supply charge (Seniors Card)', null, 'Current page (year not stated)', 'Download the form and return it to Busselton Water with a copy of your card.', null, 'https://www.busseltonwater.wa.gov.au/billing/make-a-payment/pensioner-rebates/', 'Busselton area only. No cap or phone number on page. Page lists CSHC alone, unlike Water Corporation.'),
('WA-018', 'Aqwest (Bunbury) water concession', 'Aqwest', 'State', 'WA', 'Bills', 'Discount on Bunbury water bills for pensioners and seniors.', array['PCC','DVA_GOLD','SENIORS_CARD']::text[], null, array['water_account']::text[], array[]::text[], true, 'Valid PCC, State Concession Card or WA Seniors Card (with or without CSHC). Owner-occupiers, retirement village residents, and tenants with a Pensioner or Seniors card. HCC and DVA Gold alone not eligible.', 'Discount on water charges (percentage not stated on page)', null, 'Current page (year not stated)', 'Apply online or with the PDF form; tenants with the account in landlord''s name must apply by 31 July each year.', '08 9780 9500', 'https://aqwest.com.au/your-water/accounts-billing/concessions', 'Bunbury area only. DVA_GOLD only via State Concession Card.'),
('WA-019', 'State Concession Card', 'Department of Communities', 'State', 'WA', 'Discounts', 'A WA card that gives certain DVA Gold Card holders the same rates and water rebates as pensioners.', array['DVA_GOLD']::text[], null, array['veteran']::text[], array[]::text[], true, 'DVA Gold Card holders without a PCC who are TPI, TTI, EDA, SRDP, war widows/widowers, blinded war pensioners, or other listed DVA categories.', 'Access to pensioner rebates on council rates, water service and water use charges', null, 'Ongoing', 'Download and send the State Concession Card application form.', '1800 671 233 (option 6)', 'https://www.wa.gov.au/service/community-services/grants-and-subsidies/state-concession-card', null),
('WA-020', 'WA Seniors Card', 'Department of Communities (WA Seniors Card Centre)', 'State', 'WA', 'Discounts', 'Free card for WA seniors 65+ that unlocks free off-peak public transport, rebates and business discounts.', array['NONE']::text[], null, array['aged_65']::text[], array['SENIORS_CARD']::text[], true, 'Aged 65 or over, Australian citizen or permanent resident, living in WA, and retired or working no more than 25 hours a week.', 'Free card; access to Cost of Living Rebate, free Transperth off-peak travel, rates/water rebates and discounts', null, 'Ongoing', 'Apply online at seniorscard.wa.gov.au.', '1800 671 233', 'https://www.seniorscard.wa.gov.au/eligibility/', null),
('WA-021', 'Cost of Living Rebate (WA Seniors Card)', 'Department of Communities (WA Seniors Card Centre)', 'State', 'WA', 'Payments', 'A yearly cash payment into your bank account for registered WA Seniors Card members.', array['SENIORS_CARD']::text[], null, array['aged_65']::text[], array[]::text[], true, 'Registered WA Seniors Card member; new applicants must be received by 31 May for that year''s payment.', '$114.20 single, $171.30 couple', 171.3, '2026 (paid from 23 July 2026)', 'Register your bank details with the WA Seniors Card Centre by 31 May; no need to reapply each year.', '1800 671 233', 'https://www.wa.gov.au/government/media-statements/Cook Labor Government/Cost-of-living-payments-for-Western-Australian-seniors-20260723', '$171.30 is per couple; single max $114.20.'),
('WA-022', 'Safety and Security Rebate', 'Department of Communities (WA Seniors Card Centre)', 'State', 'WA', 'Home and Rates', 'Get back up to $400 for buying home security or safety items like alarms, screens, deadlocks or smoke alarms.', array['SENIORS_CARD']::text[], null, array['aged_65']::text[], array[]::text[], true, 'WA Seniors Card member at the time of purchase; item installed at your principal WA home. Not for aged care, hospital or hostel residents. One claim per household.', 'One-off rebate up to $400 for eligible items bought on or after 22 Aug 2021', null, 'Ongoing since 22 Aug 2021 (no end date set)', 'Buy and install the item, then apply online or by form with tax receipts and ID.', '1800 671 233', 'https://www.seniorscard.wa.gov.au/safety-and-security-rebate-terms/', 'One-off ($400 lifetime per household) so max_annual_value null.'),
('WA-023', 'Transperth free off-peak travel (Seniors SmartRider)', 'Transperth (Public Transport Authority)', 'State', 'WA', 'Transport', 'Free bus, train and ferry travel in Perth at off-peak times and weekends for WA Seniors Card holders.', array['SENIORS_CARD']::text[], null, array['aged_65']::text[], array[]::text[], true, 'WA Seniors Card holder using a Seniors SmartRider.', 'Free 9am to 3:30pm and 7pm to 6am weekdays, all weekend, public holidays and Seniors Week; concession fares at other times', null, 'Current', 'Get a Seniors SmartRider linked to your WA Seniors Card.', '13 62 13', 'https://www.seniorscard.wa.gov.au/benefits', 'Phone 13 62 13 is Transperth''s InfoLine (not on source page; verify).'),
('WA-024', 'Transperth Pensioner and Veteran SmartRider', 'Transperth (Public Transport Authority)', 'State', 'WA', 'Transport', 'Concession fares and free travel on Perth public transport for age pensioners, carers and veterans.', array['PCC','DVA_GOLD','HCC']::text[], null, array['age_pension']::text[], array[]::text[], true, 'Aged pensioners and carers (Pensioner SmartRider), veterans/war widows (Veteran SmartRider). HCC holders get concession fares only.', 'Concession fare or free travel (times not stated on page)', null, 'Current', 'Get a Pensioner or Veteran SmartRider.', null, 'https://www.transperth.wa.gov.au/tickets-fares/concession-guide', 'Free travel times not stated on the Transperth page; HCC is concession fare only.'),
('WA-025', 'Transwa regional coach and rail concession', 'Transwa', 'State', 'WA', 'Transport', 'Half-price regional train and coach fares across WA.', array['PCC','SENIORS_CARD','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'Pensioner Concession Card, State-issued Seniors card or Seniors SmartRider, Veteran SmartRider, DVA PCC or Gold Card. CSHC alone does not qualify.', '50% off the regular fare', null, 'Current', 'Book online (registered cardholders) or by phone/booking centre.', '1300 662 205', 'https://www.transwa.wa.gov.au/fares/concessions', null),
('WA-026', 'Transwa Pensioner Free Travel', 'Transwa', 'State', 'WA', 'Transport', 'Free regional train or coach trips each year for WA pensioners and DVA Gold Card holders.', array['PCC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, 'WA Pensioner Concession Card (Services Australia or DVA) holders, and WA DVA Gold Card holders.', '2 free single trips a year (PCC) or 4 (DVA Gold), plus 50% off other fares', null, 'Per calendar year', 'Register online, by phone, post or at a booking centre (up to 10 business days).', '1300 662 205', 'https://www.transwa.wa.gov.au/fares/pensioner-free-travel', 'Dollar value depends on route.'),
('WA-027', 'Regional Pensioner Travel Card', 'DPIRD (managed by WEX Australia)', 'State', 'WA', 'Transport', 'A card loaded with a set amount each year for fuel or taxis, for pensioners living in regional WA.', array['PCC','DVA_GOLD']::text[], null, array['age_pension','rural']::text[], array[]::text[], true, 'Receiving a means-tested pension (Age Pension, Carer Payment, DSP, DVA Service Pension, Income Support Supplement) and living in an eligible regional location.', 'Set amount each year for fuel and/or taxis (amount not stated on page)', null, 'Financial year', 'Get the form from a participating Australia Post office and submit by 15 May for the coming financial year.', '1300 666 609', 'https://www.wa.gov.au/service/community-services/rural-community-development/regional-pensioner-travel-card', 'Replaces the Country Age Pension Fuel Card. Annual dollar amount not on source. From 1 Oct 2026 fuel retailers may surcharge.'),
('WA-028', 'Vehicle licence (registration) concession', 'Department of Transport', 'State', 'WA', 'Transport', 'Half off the vehicle licence fee on one car for pensioners and Seniors Card plus CSHC holders.', array['PCC','SENIORS_CARD','CSHC']::text[], '[["PCC"],["SENIORS_CARD","CSHC"]]'::jsonb, array['car_owner']::text[], array[]::text[], true, 'Pensioner Concession Card (Centrelink or DVA), or BOTH a WA Seniors Card and CSHC. One vehicle only (car, light goods under 3t, motorhome, motorcycle). 100% for certain veterans (TPI/EDA/SRDP) and max-rate DSP/carer/blind pensioners.', '50% off the vehicle licence fee (100% for some veterans and disability pensioners)', null, 'Current', 'Fill in the C1 Application for concession form and show your card(s).', '13 11 56', 'https://transport.wa.gov.au/about-us/concessions/seniors-veterans-pensioners', 'Phone from WA Seniors Card benefits page.'),
('WA-029', 'Driver''s licence fee concession', 'Department of Transport', 'State', 'WA', 'Transport', 'Free or half-price driver''s licence renewal for pensioners and seniors.', array['PCC','SENIORS_CARD','CSHC','DVA_GOLD']::text[], null, array[]::text[], array[]::text[], true, '100% free: PCC holders on the Age Pension, or WA Seniors Card + CSHC, or DVA Gold TPI/EDA/SRDP. 50% off: PCC (Centrelink or DVA) or WA Seniors Card.', '100% or 50% off licence renewal/replacement fees', null, 'Current', 'Show your card(s) when renewing; use the C1 form. Refunds may apply if you paid full fees while eligible.', '13 11 56', 'https://transport.wa.gov.au/about-us/concessions/seniors-veterans-pensioners', null),
('WA-030', 'WA Photo Card fee concession', 'Department of Transport', 'State', 'WA', 'Discounts', 'Free or half-price WA Photo Card (ID card) for pensioners and seniors.', array['PCC','SENIORS_CARD','CSHC']::text[], null, array[]::text[], array[]::text[], true, 'Same rules as driver''s licence: free for Age Pension PCC holders or Seniors Card + CSHC; 50% off for PCC or Seniors Card.', '100% or 50% off Photo Card fee', null, 'Current', 'Show your card(s) when applying.', '13 11 56', 'https://transport.wa.gov.au/about-us/concessions/seniors-veterans-pensioners', null),
('WA-031', 'Recreational fishing licence discount', 'DPIRD', 'State', 'WA', 'Discounts', 'Half-price recreational fishing licences for WA Seniors Card holders.', array['SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'WA Seniors Card holders (other concession cards may also qualify; DPIRD page''s concession section did not load).', '50% off recreational fishing licences (standard fees $40-$50)', null, 'Current', 'Buy your licence online through DPIRD and select the concession.', '1300 374 731', 'https://www.seniorscard.wa.gov.au/benefits', 'Concession detail missing on DPIRD page; PCC eligibility not confirmed.'),
('WA-032', 'Ambulance fee subsidy (St John WA)', 'WA Department of Health / St John WA', 'State', 'WA', 'Health', 'Free ambulance for over-65 pensioners, and half price for other over-65s or under-65 pensioners.', array['PCC','NONE']::text[], null, array[]::text[], array[]::text[], true, 'WA residents over 65 with a pension concession entitlement: free. Over 65 without one, or under 65 with one: pay 50%. Service must be medically necessary.', 'Free (65+ with pension concession) or 50% off ambulance fees', null, 'Current', 'Contact St John''s Finance Customer Team about your bill.', '(08) 9334 1212', 'https://stjohnwa.com.au/ambulance-and-health-services/ambulance-service/pay-my-bill/pensioner-over-65', 'Applies with no card if aged 65+ (50%); use aged_65 logic manually. Page only says ''Pension Concession Entitlement''.'),
('WA-033', 'Public dental care for adults', 'Dental Health Services (WA Health)', 'State', 'WA', 'Health', 'Subsidised general and emergency dental care at public clinics for concession card holders.', array['PCC','HCC']::text[], null, array[]::text[], array[]::text[], true, 'Aged 17+ with a current Health Care Card or Pensioner Concession Card. Includes the Country and Metropolitan Patients Dental Subsidy Schemes (private dentists).', 'Subsidised dental care (co-payment not stated)', null, 'Current', 'Phone Dental Health Services to get on the waiting list.', '(08) 9313 0555', 'https://www.health.wa.gov.au/Articles/A_E/Dental-Health-Services', 'Patient co-payment amounts not on page.'),
('WA-034', 'Spectacle Subsidy Scheme', 'WA Department of Health', 'State', 'WA', 'Health', 'Up to $54.34 every two years towards glasses or contact lenses.', array['PCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Receive an Age, Disability or Service pension, or hold a WA Seniors Card. DVA Gold Card holders not eligible.', 'Up to $54.34 every 2 years', null, 'Rate since 1 July 2019', 'Ask your optometrist for the claim form when you buy your glasses.', '13 44 77 (option 3, then 4)', 'https://www.healthywa.wa.gov.au/Articles/S_T/Spectacle-Subsidy-Scheme', 'Paid every 2 years so max_annual_value null (about $27/yr).'),
('WA-035', 'Patient Assisted Travel Scheme (PATS)', 'WA Country Health Service', 'State', 'WA', 'Health', 'Helps country people with travel and accommodation costs to reach specialist treatment far from home.', array['NONE']::text[], null, array['rural']::text[], array[]::text[], true, 'Country WA residents travelling over 100 km (70-100 km for cancer/renal) to the nearest eligible specialist service, assessed under the PATS Handbook. From 1 July 2026 also covers approved specialist allied health and dental.', '40c per km fuel; accommodation $20/night private or up to $110/night commercial (+$15 support person); $20 per return trip for 70-100 km cancer/renal', null, 'From July 2025 (fuel rate); current page', 'Get your specialist/GP to sign the PATS form and lodge it with your local PATS office.', null, 'https://wacountry.health.wa.gov.au/Our-patients/Patient-Assisted-Travel-Scheme-PATS/PATS-subsidies', 'No card needed; phone via local PATS office.'),
('WA-036', 'Community Aids and Equipment Program (CAEP)', 'WA Department of Health', 'State', 'WA', 'Health', 'Equipment like wheelchairs and home changes like ramps for people with long-term or age-related impairment living at home.', array['NONE']::text[], null, array['mobility_need']::text[], array[]::text[], true, 'People living at home with long-term health conditions, disability or age-related functional impairment, assessed by a health professional.', 'Equipment and home modifications (cost to client not stated)', null, 'Current', 'Ask your GP or allied health professional to complete the CAEP Referral Form.', null, 'https://www.wa.gov.au/service/health-care/community-health-services/community-aids-and-equipment-program-caep', 'Card/income criteria not on page.'),
('WA-037', 'Dog and cat registration discount', 'Local councils (under DLGSC rules)', 'State', 'WA', 'Discounts', 'Cheaper dog and cat registration for concession card holders.', array['PCC']::text[], null, array[]::text[], array[]::text[], true, 'Dog: Pensioner Concession Card holders. Cat: accepted concession card holders.', 'Discounted registration (amount not stated)', null, 'Current', 'Show your card when registering your pet with your council.', null, 'https://www.wa.gov.au/organisation/department-of-communities/concessions-available-western-australia', 'Level is State law applied by councils.'),
('WA-038', 'Public Trustee will drafting discount', 'Public Trustee WA (Department of Justice)', 'State', 'WA', 'Discounts', 'A cheaper fee to have the Public Trustee write your will if you hold a concession card.', array['PCC','HCC','SENIORS_CARD']::text[], null, array[]::text[], array[]::text[], true, 'Valid concession card holders (exact cards not stated on master list).', 'Discounted will drafting fee (amount not stated)', null, 'Current', 'Contact the Public Trustee to book a will appointment.', null, 'https://www.wa.gov.au/organisation/department-of-communities/concessions-available-western-australia', 'Eligible cards to confirm on Public Trustee page.'),
('WA-039', 'Attractions and parks concessions', 'WA Government agencies', 'State', 'WA', 'Discounts', 'Discounted entry to Perth Zoo, WA Museum, national parks, Rottnest Island and other state attractions.', array['SENIORS_CARD','PCC']::text[], null, array[]::text[], array[]::text[], true, 'Concession card holders; WA Seniors Card holders get discounts at the Art Gallery of WA, WA Museum, Perth Zoo, national parks and Rottnest accommodation.', 'Discounted entry (varies by venue)', null, 'Current', 'Show your card at the venue or when booking.', null, 'https://www.seniorscard.wa.gov.au/benefits', 'Bundled record; individual prices not loaded.'),
('WA-040', 'Land tax concession for veterans'' surviving partners', 'RevenueWA (Department of Finance)', 'State', 'WA', 'Home and Rates', 'Lower land tax for eligible war widows, war widowers and widowed mothers of veterans.', array['DVA_GOLD']::text[], null, array['veteran','homeowner']::text[], array[]::text[], true, 'Eligible war widows, war widowers or veterans'' widowed mothers.', 'Reduced assessable land value (amount not stated)', null, 'Current', 'Apply for a land tax exemption with RevenueWA.', '08 9262 1373', 'https://www.wa.gov.au/organisation/department-of-communities/concessions-available-western-australia', 'Only matters if land tax applies (most owner-occupied homes are already exempt).')
